function tkFit(all){const t=S.tk;const c=$('#tk-canvas');if(!c)return;const W=c.clientWidth,H=c.clientHeight;let pts=[];
  const cur=tkSheetCorners(t.page);if(cur&&!all)pts=cur;
  else{pts=[...(t.perim||[]),...t.lines.flatMap(l=>l.pts)];[tkSurfBBox('ex'),tkSurfBBox('pr')].forEach(b=>{if(b)pts.push([b.x0,b.y0],[b.x1,b.y1])});if(cur)pts.push(...cur)}
  let bx=0,by=0,bw=1000,bh=700;if(pts.length){const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);bx=Math.min(...xs);by=Math.min(...ys);bw=Math.max(...xs)-bx||100;bh=Math.max(...ys)-by||100}
  const z=Math.min(W/bw,H/bh)*0.95;t.view={z,ox:(W-bw*z)/2-bx*z,oy:(H-bh*z)/2-by*z}}
