const ptB64=buf=>{const u=new Uint8Array(buf);let s='';for(let i=0;i<u.length;i+=0x8000)s+=String.fromCharCode.apply(null,u.subarray(i,i+0x8000));return btoa(s)};
const ptBytes=b64=>{const s=atob(b64);const u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return u};
function ptSave(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000)}
async function ptFetch(id){const rows=await run(sb.from('proposal_templates').select('*').eq('id',id));const t=rows&&rows[0];if(!t||!t.file)throw new Error('That template is gone.');return t}
async function ptFill(id){const E=S.est;if(!E||!E.data||!id)return;const b=byId(S.bids,E.bidId)||{};toast('Filling your template…');
  try{const [JSZip,t]=await Promise.all([loadJSZip(),ptFetch(id)]);const zip=await JSZip.loadAsync(ptBytes(t.file));const unk=await ptFillZip(zip,t.kind,ptData());
    const blob=await zip.generateAsync({type:'blob',mimeType:PT_MIME[t.kind],compression:'DEFLATE'});const safe=String(b.name||'Proposal').replace(/[\\/:*?"<>|]+/g,' ').trim();ptSave(blob,`Proposal - ${safe}.${t.kind}`);
    toast(unk.length?`Downloaded. ${unk.length} field${unk.length===1?'':'s'} in the template ${unk.length===1?'isn’t one':'aren’t ones'} the app knows: ${unk.slice(0,4).map(x=>'{{'+x+'}}').join(', ')}${unk.length>4?'…':''}`:'Proposal downloaded')}
  catch(e){toast(/proposal_templates|does not exist|schema cache/i.test(errMsg(e))?PT_SQL:errMsg(e))}}
async function ptUpload(file){if(!file||!isAdmin())return;const ext=(/\.([a-z0-9]+)$/i.exec(file.name)||[])[1]?.toLowerCase();
  if(ext!=='docx'&&ext!=='xlsx'){toast(ext==='doc'||ext==='xls'?'Save it as .docx or .xlsx first (File → Save As), then upload that.':'Upload a Word (.docx) or Excel (.xlsx) file.');return}
  if(file.size>4*1024*1024){toast('That file is over 4 MB. Shrink the logo or pictures in it and try again.');return}
  try{const buf=await file.arrayBuffer();const JSZip=await loadJSZip();const zip=await JSZip.loadAsync(buf);if(!zip.file(ext==='docx'?'word/document.xml':'xl/workbook.xml'))throw new Error(`That doesn’t look like a real .${ext} file.`);
    let found=0;for(const p of Object.keys(zip.files).filter(p=>/^(word\/(document|header\d*|footer\d*)\.xml|xl\/(sharedStrings|worksheets\/[^/]+)\.xml)$/.test(p))){const x=(await zip.file(p).async('string')).replace(/<[^>]+>/g,'');found+=(x.match(PT_RE)||[]).length}
    await run(sb.from('proposal_templates').insert({id:newId(),name:file.name.replace(/\.[^.]+$/,''),kind:ext,filename:file.name,size:file.size,file:ptB64(buf),created_by_name:myName()}));await loadPropTpls();if(M&&M.kind==='pt')renderModal();render();
    toast(found?`Template added — ${found} field${found===1?'':'s'} found in it`:'Template added, but it has no {{fields}} in it yet. See the field list.')}
  catch(e){toast(/proposal_templates|does not exist|schema cache/i.test(errMsg(e))?PT_SQL:errMsg(e))}}
async function ptStarter(kind){try{const JSZip=await loadJSZip();const zip=new JSZip();const x=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    zip.file('_rels/.rels',XML_HEAD+`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="${kind==='docx'?'word/document.xml':'xl/workbook.xml'}"/></Relationships>`);
    if(kind==='docx'){const p=(t,b)=>`<w:p><w:r>${b?'<w:rPr><w:b/></w:rPr>':''}<w:t xml:space="preserve">${x(t)}</w:t></w:r></w:p>`;const tc=(t,w)=>`<w:tc><w:tcPr><w:tcW w:w="${w}" w:type="dxa"/></w:tcPr>${p(t)}</w:tc>`;const tr=c=>`<w:tr>${c.map(([t,w])=>tc(t,w)).join('')}</w:tr>`;
      const bd='<w:tblPr><w:tblW w:w="0" w:type="auto"/><w:tblBorders><w:top w:val="single" w:sz="4" w:color="999999"/><w:bottom w:val="single" w:sz="4" w:color="999999"/><w:insideH w:val="single" w:sz="4" w:color="CCCCCC"/></w:tblBorders></w:tblPr>';
      const W=[900,4200,1000,800,1300,1500];
      zip.file('[Content_Types].xml',XML_HEAD+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');
      zip.file('word/document.xml',XML_HEAD+`<w:document xmlns:w="${W_NS}"><w:body>${p('{{company}}',1)}${p('{{letterhead}}')}${p('')}${p('PROPOSAL',1)}${p('Date: {{date}}')}${p('To: {{client}}   Attn: {{attn}}')}${p('Project: {{project}} — {{location}}')}${p('')}${p('{{intro}}')}${p('Basis: {{basis}}')}${p('')}
        <w:tbl>${bd}${tr(['Item','Description','Qty','Unit','Unit price','Amount'].map((t,i)=>[t,W[i]]))}${tr(['{{item.code}}','{{item.desc}}','{{item.qty}}','{{item.unit}}','{{item.unit_price}}','{{item.amount}}'].map((t,i)=>[t,W[i]]))}${tr(['','Total base bid','','','','{{total}}'].map((t,i)=>[t,W[i]]))}</w:tbl>
        ${p('')}${p('Alternates',1)}<w:tbl>${bd}${tr([['{{alt.code}}',900],['{{alt.desc}}',6000],['{{alt.amount}}',2800]])}</w:tbl>${p('')}${p('Inclusions',1)}${p('{{inclusions}}')}${p('Exclusions',1)}${p('{{exclusions}}')}${p('Clarifications',1)}${p('{{clarifications}}')}${p('')}${p('{{terms}} This proposal is valid for {{valid_days}} days.')}${p('')}${p('{{signed_by}}')}${p('{{title}}')}
        <w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1080" w:right="1080" w:bottom="1080" w:left="1080" w:header="720" w:footer="720" w:gutter="0"/></w:sectPr></w:body></w:document>`)}
    else{const col=i=>String.fromCharCode(65+i);const row=(n,c)=>`<row r="${n}">${c.map((t,i)=>t===''?'':String(t).startsWith('=')?`<c r="${col(i)}${n}"><f>${x(String(t).slice(1))}</f></c>`:`<c r="${col(i)}${n}" t="inlineStr"><is><t xml:space="preserve">${x(t)}</t></is></c>`).join('')}</row>`;
      zip.file('[Content_Types].xml',XML_HEAD+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');
      zip.file('xl/workbook.xml',XML_HEAD+`<workbook xmlns="${X_NS}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Proposal" sheetId="1" r:id="rId1"/></sheets></workbook>`);
      zip.file('xl/_rels/workbook.xml.rels',XML_HEAD+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>');
      zip.file('xl/worksheets/sheet1.xml',XML_HEAD+`<worksheet xmlns="${X_NS}"><cols><col min="1" max="1" width="10" customWidth="1"/><col min="2" max="2" width="46" customWidth="1"/><col min="3" max="6" width="14" customWidth="1"/></cols><sheetData>${[row(1,['{{company}}']),row(2,['PROPOSAL']),row(3,['Project','{{project}}']),row(4,['Location','{{location}}']),row(5,['To','{{client}}']),row(6,['Date','{{date}}']),
        row(8,['Item','Description','Qty','Unit','Unit price','Amount']),row(9,['{{item.code}}','{{item.desc}}','{{item.qty}}','{{item.unit}}','{{item.unit_price}}','=C9*E9']),row(10,['','Total base bid','','','','{{total}}']),row(12,['Inclusions','{{inclusions}}']),row(13,['Exclusions','{{exclusions}}']),row(14,['Signed','{{signed_by}}, {{title}}'])].join('')}</sheetData></worksheet>`)}
    ptSave(await zip.generateAsync({type:'blob',mimeType:PT_MIME[kind],compression:'DEFLATE'}),`Proposal starter template.${kind}`)}catch(e){toast(errMsg(e))}}
function ptPanel(ro){const ts=S.propTpls||[];if(!ts.some(t=>t.id===S.ptSel))S.ptSel=ts[0]?.id||'';
  return `<div class="panel pad"><h3 class="pr-h">Your own Word / Excel template</h3>
    ${S.propTplMissing?`<p class="hint">${PT_SQL}</p>`:ts.length?`<div class="pt-row"><select class="field" id="pt-sel" data-ptsel aria-label="Template">${ts.map(t=>`<option value="${t.id}"${t.id===S.ptSel?' selected':''}>${esc(t.name)} (${t.kind==='docx'?'Word':'Excel'})</option>`).join('')}</select><button class="btn primary" data-act="pt-fill">Fill &amp; download</button></div>`
      :`<p class="small dim" style="margin:0 0 8px">No company templates yet.${isAdmin()?' Upload your Word or Excel proposal and the app fills it in for each bid.':' An admin can upload your Word or Excel proposal.'}</p>`}
    <div class="pr-actions" style="margin-top:8px">${isAdmin()?'<button class="btn sm" data-act="pt-open">Manage templates</button>':''}<button class="btn sm ghost" data-act="pt-open">Field list</button></div>
    <p class="hint">Fills your file with this estimate’s project, GC, bid items, prices and wording. The built-in proposal on the right stays as it is — use either one.</p></div>`}
function ptModal(){const ts=S.propTpls||[];const adm=isAdmin();
  return mhead('Proposal templates','Your own Word and Excel files, filled in by the app')+`<div class="mbody">
    ${S.propTplMissing?`<div class="notice">${PT_SQL}</div>`:''}
    <fieldset><legend>Company templates (${ts.length})</legend>
      ${ts.map(t=>`<div class="sv-row"><div><b>${esc(t.name)}</b> ${pill(t.kind==='docx'?'Word':'Excel')}<div class="small dim">${esc(t.filename||'')} · ${fmtN((t.size||0)/1024,0)} KB${t.updated_at?' · '+fmtShort(String(t.updated_at).slice(0,10)):''}${t.created_by_name?' · '+esc(t.created_by_name):''}</div></div><div></div>
        <div class="rev-btns"><button class="btn sm" data-act="pt-dl" data-id="${t.id}">Download</button>${adm?`<button class="btn sm" data-act="pt-rename" data-id="${t.id}">Rename</button><button class="btn sm danger${M.arm2===t.id?' arm':''}" data-act="pt-del" data-id="${t.id}">${M.arm2===t.id?'Click again':'Delete'}</button>`:''}</div></div>`).join('')||'<p class="small dim">None yet.</p>'}
      ${adm?`<div class="pt-up"><label class="btn primary">Upload a .docx or .xlsx<input type="file" accept=".docx,.xlsx" data-ptup hidden></label><button class="btn" data-act="pt-starter" data-v="docx">Download a Word starter</button><button class="btn" data-act="pt-starter" data-v="xlsx">Download an Excel starter</button></div>`:''}</fieldset>
    <fieldset><legend>How to build one</legend><ol class="pt-how"><li>Open your proposal in Word or Excel (or start from a starter file).</li><li>Wherever the app should fill something in, type the field name in double curly braces, like <code>{{project}}</code> or <code>{{total}}</code>. Keep your own fonts, logo and layout.</li>
      <li>For the list of bid items, make <b>one</b> table row with the <code>{{item.…}}</code> fields. The app repeats that row for every bid item. Same for <code>{{scope.…}}</code> and <code>{{alt.…}}</code>.</li><li>Save as .docx or .xlsx and upload it here. To change a template, upload the new file and delete the old one.</li></ol>
      <p class="hint">Excel: a cell holding only a number field (like <code>{{item.amount}}</code>) becomes a real number, so your own number formats and formulas work. Formulas in the repeated row are copied down, and a SUM range that ends on that row grows with it.</p></fieldset>
    <fieldset><legend>Field list</legend>${PT_FIELDS.map(([h,fs])=>`<div class="pt-fh">${esc(h)}</div><div class="pt-fields">${fs.map(([k,l])=>`<div><code>{{${k}}}</code><span>${esc(l)}</span></div>`).join('')}</div>`).join('')}</fieldset></div>
  <div class="mfoot"><div></div><div class="r"><button class="btn" data-act="close">Close</button></div></div>`}
document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t||t.tagName==='SELECT')return;const a=t.dataset.act;if(!a.startsWith('pt-'))return;
  switch(a){
    case 'pt-fill':ptFill($('#pt-sel')?.value||S.ptSel);break;
    case 'pt-open':M={kind:'pt'};showModal();loadJSZip().catch(()=>{});break;
    case 'pt-starter':ptStarter(t.dataset.v);break;
    case 'pt-dl':(async()=>{try{const x=await ptFetch(t.dataset.id);ptSave(new Blob([ptBytes(x.file)],{type:PT_MIME[x.kind]}),x.filename||x.name+'.'+x.kind)}catch(er){toast(errMsg(er))}})();break;
    case 'pt-rename':{const x=S.propTpls.find(p=>p.id===t.dataset.id);if(!x||!isAdmin())break;const n=(prompt('Template name',x.name)||'').trim();if(!n||n===x.name)break;run(sb.from('proposal_templates').update({name:n}).eq('id',x.id)).then(loadPropTpls).then(()=>{renderModal();render()}).catch(er=>toast(errMsg(er)));break}
    case 'pt-del':{if(!isAdmin())break;if(M.arm2!==t.dataset.id){M.arm2=t.dataset.id;renderModal();break}M.arm2=null;run(sb.from('proposal_templates').delete().eq('id',t.dataset.id)).then(loadPropTpls).then(()=>{renderModal();render()}).catch(er=>toast(errMsg(er)));break}
  }});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.ptsel!=null){S.ptSel=t.value;return}if(t.dataset.ptup!=null){const f=t.files&&t.files[0];t.value='';ptUpload(f)}});

/* =====================================================================
   Schedule (Gantt): one bar per bid item, filled in from the estimate.
   Days come from crew hours ÷ hours per day; each item starts after the
   one before it until you say otherwise. Saved in the estimate (data.gantt).
   ===================================================================== */
function ganttData(d){if(!d.gantt||typeof d.gantt!=='object')d.gantt={start:'',rows:{}};if(!d.gantt.rows||typeof d.gantt.rows!=='object')d.gantt.rows={};return d.gantt}
function ganttCalc(d,R){R=R||estCalc(d);const G=d.gantt&&d.gantt.rows?d.gantt:{start:'',rows:{}};const wk=Math.min(7,Math.max(1,Math.round(num(R.ctx.days)||5)));
  const rows=d.items.map((it,i)=>({it,x:R.items[i]})).filter(o=>!o.it.alt).map((o,i)=>{const g=G.rows[o.it.id]||{};const cd=o.x.acts.reduce((s,a)=>s+(a.days||0),0);const auto=cd>0?Math.max(1,Math.ceil(cd-1e-9)):0;
    const manual=g.dur!=null&&g.dur!=='';return {id:o.it.id,it:o.it,sec:o.it.sec,auto,crewDays:cd,manual,dur:manual?Math.max(0,Math.round(num(g.dur)||0)):(auto||1),pred:g.pred,lag:Math.round(num(g.lag)||0)}});
  const by=new Map(rows.map(r=>[r.id,r]));rows.forEach((r,i)=>{r.predId=r.pred==='start'?null:r.pred&&by.has(r.pred)&&r.pred!==r.id?r.pred:r.pred?null:(i?rows[i-1].id:null);r.predAuto=!r.pred});
  const seen=new Set();const place=r=>{if(r.start!=null)return;if(seen.has(r.id)){r.start=0;r.loop=true;return}seen.add(r.id);const p=r.predId&&by.get(r.predId);if(p)place(p);r.start=Math.max(0,(p?p.start+p.dur:0)+r.lag);r.end=r.start+r.dur};
  rows.forEach(r=>{place(r);r.end=r.start+r.dur});const total=rows.reduce((m,r)=>Math.max(m,r.end),0);
  const isWork=dt=>{const w=dt.getDay();return wk>=7||(wk===6?w!==0:w!==0&&w!==6)};
  const s0=new Date((G.start||todayStr())+'T12:00:00');while(!isWork(s0))s0.setDate(s0.getDate()+1);
  const cache=[new Date(s0)];const dateAt=n=>{n=Math.max(0,Math.round(n));while(cache.length<=n){const x=new Date(cache[cache.length-1]);do{x.setDate(x.getDate()+1)}while(!isWork(x));cache.push(x)}return cache[n]};
  const iso=dt=>dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0');
  rows.forEach(r=>{r.startDate=iso(dateAt(r.start));r.endDate=iso(dateAt(Math.max(r.start,r.end-1)))});
  return {rows,total,wk,weeks:total/wk,hasStart:!!G.start,startDate:iso(s0),finishDate:total?iso(dateAt(total-1)):iso(s0),dateAt,iso}}
const ganttWeeksText=g=>g.total?`${g.total} working day${g.total===1?'':'s'} (about ${fmtN(Math.max(1,Math.ceil(g.weeks-1e-9)),0)} week${Math.ceil(g.weeks-1e-9)<=1?'':'s'})`:'';
function ganttBars(d,g,o={}){const px=o.px||Math.max(5,Math.min(26,Math.floor((o.width||880)/Math.max(1,g.total))));const W=Math.max(1,g.total)*px;const step=g.total>90?g.wk*2:g.wk;
  const ticks=[];for(let n=0;n<g.total;n+=step)ticks.push(`<span class="gt-tick" style="left:${n*px}px">${g.hasStart?fmtShort(g.iso(g.dateAt(n))):'Wk '+(Math.round(n/g.wk)+1)}</span>`);
  const grid=`background-size:${g.wk*px}px 100%`;const out=[];
  (d.sections||[]).forEach(s=>{const rs=g.rows.filter(r=>r.sec===s.id);if(!rs.length)return;const a=Math.min(...rs.map(r=>r.start)),z=Math.max(...rs.map(r=>r.end));
    out.push({sec:s,head:`<div class="gt-bar gt-sum" style="left:${a*px}px;width:${Math.max(2,(z-a)*px)}px"></div>`,days:z-a});rs.forEach(r=>out.push({r,head:`<div class="gt-bar${r.auto||r.manual?'':' gt-guess'}" style="left:${r.start*px}px;width:${Math.max(3,r.dur*px)}px" title="${esc(r.it.desc||'')}: ${r.dur} day${r.dur===1?'':'s'}"></div>`}))});
  return {px,W,ticks:ticks.join(''),grid,out}}
function estGanttView(d,R,ro){const G=ganttData(d);const g=ganttCalc(d,R);const dis=ro?' disabled':'';if(!g.rows.length)return `<div class="panel pad"><div class="empty"><b>No bid items yet</b>Add bid items on the Build tab and the schedule fills itself in.</div></div>`;
  const B=ganttBars(d,g);const custom=Object.values(G.rows).some(x=>x&&(x.dur!=null&&x.dur!==''||x.pred||x.lag));const indDays=Math.round(R.dur.days||0);
  const opts=r=>`<option value=""${r.pred?'':' selected'}>After the item above</option><option value="start"${r.pred==='start'?' selected':''}>At project start</option>${g.rows.filter(x=>x.id!==r.id).map(x=>`<option value="${x.id}"${r.pred===x.id?' selected':''}>After ${esc((x.it.code?x.it.code+' ':'')+(x.it.desc||'item')).slice(0,60)}</option>`).join('')}`;
  const body=B.out.map(o=>o.sec?`<tr class="gt-sec"><td colspan="5"><b>${esc(o.sec.name||'Section')}</b> <span class="dim small">${o.days} day${o.days===1?'':'s'}</span></td><td class="gt-track" style="${B.grid}"><div class="gt-in" style="width:${B.W}px">${o.head}</div></td></tr>`
    :`<tr><td class="gt-code">${esc(o.r.it.code||'')}</td><td class="gt-desc">${esc(o.r.it.desc||'')}${o.r.loop?' <span class="warn-t small">starts-after loop</span>':''}</td>
      <td><input class="field num gt-n" id="gd-${o.r.id}" data-gd="${o.r.id}" inputmode="numeric" value="${o.r.manual?o.r.dur:''}" placeholder="${o.r.auto||1}" title="${o.r.auto?`From the estimate: ${fmtN(o.r.crewDays,1)} crew days`:'No crew hours on this item — type the days'}"${dis}></td>
      <td><select class="field gt-p" data-gp="${o.r.id}" aria-label="Starts"${dis}>${opts(o.r)}</select></td>
      <td><input class="field num gt-n" id="gl-${o.r.id}" data-gl="${o.r.id}" inputmode="numeric" value="${o.r.lag||''}" placeholder="0" title="Days to wait after that (negative to overlap)"${dis}></td>
      <td class="gt-track" style="${B.grid}"><div class="gt-in" style="width:${B.W}px">${o.head}<span class="gt-lab" style="left:${o.r.end*B.px+6}px">${g.hasStart?fmtShort(o.r.startDate)+' – '+fmtShort(o.r.endDate):o.r.dur+'d'}</span></div></td></tr>`).join('');
  return `<div class="panel pad gt-top"><div class="gt-sumline"><div><span>Duration</span><b>${g.total} working days</b><small>${fmtN(g.weeks,1)} weeks at ${g.wk} days a week</small></div>
      <div><span>Start</span><input class="field" type="date" id="gt-start" data-gs value="${esc(G.start||'')}"${dis}><small>${G.start?'':'No date yet — showing weeks'}</small></div>
      <div><span>Finish</span><b>${G.start?fmtDate(g.finishDate):'—'}</b><small>${G.start?'last working day':'set a start date'}</small></div>
      <div><span>Indirects use</span><b>${indDays} days</b><small>${indDays===g.total?'matches this schedule':'from Schedule & indirects'}</small></div></div>
    <div class="adders" style="margin:10px 0 0">${ro?'':`${indDays!==g.total?`<button class="btn sm primary" data-act="gt-useind" title="Sets the job duration on Schedule & indirects to ${g.total} days">Use ${g.total} days for indirects</button>`:''}<button class="btn sm" data-act="gt-reset"${custom?'':' disabled'}>Reset to the estimate</button>`}<button class="btn sm" data-act="gt-print">Print</button><button class="btn sm" data-act="gt-csv">Export (Excel / CSV)</button></div>
    <p class="hint">Days come from each bid item’s crew hours. Items with no crew (subs, materials only) start at 1 day and show hatched — type the real number. Each item starts after the one above it; change <b>Starts</b> to run items side by side. Alternates aren’t scheduled.</p></div>
  <div class="panel gt-wrap" id="gt-paper"><div class="gt-scroll"><table class="gt"><thead><tr><th>Item</th><th>Description</th><th>Days</th><th>Starts</th><th>Wait</th><th class="gt-track"><div class="gt-in gt-head" style="width:${B.W}px">${B.ticks}</div></th></tr></thead><tbody>${body}</tbody></table></div></div>`}
// compact, read-only chart for the proposal
function ganttPaper(d,R){const g=ganttCalc(d,R);if(!g.rows.length)return '';const B=ganttBars(d,g,{width:330});
  return `<table class="pp-gt"><thead><tr><th>Item</th><th class="r">Days</th><th class="gt-track"><div class="gt-in gt-head" style="width:${B.W}px">${B.ticks}</div></th></tr></thead><tbody>${B.out.map(o=>o.sec?`<tr class="gt-sec"><td colspan="2"><b>${esc(o.sec.name||'')}</b></td><td class="gt-track" style="${B.grid}"><div class="gt-in" style="width:${B.W}px">${o.head}</div></td></tr>`
    :`<tr><td>${esc(o.r.it.desc||'')}</td><td class="r">${o.r.dur}</td><td class="gt-track" style="${B.grid}"><div class="gt-in" style="width:${B.W}px">${o.head}</div></td></tr>`).join('')}</tbody></table>`}
function ganttCsv(d){const g=ganttCalc(d);const b=byId(S.bids,S.est.bidId)||{};const q=v=>'"'+String(v==null?'':v).replace(/"/g,'""')+'"';const by=new Map(g.rows.map(r=>[r.id,r]));
  const lines=[['Section','Item','Description','Working days','Starts after','Wait (days)','Start day #','Finish day #',...(g.hasStart?['Start date','Finish date']:[])].map(q).join(',')];
  g.rows.forEach(r=>{const p=r.predId&&by.get(r.predId);lines.push([(secOf(d,r.sec)||{}).name||'',r.it.code||'',r.it.desc||'',r.dur,p?((p.it.code?p.it.code+' ':'')+(p.it.desc||'')):'Project start',r.lag,r.start+1,r.end,...(g.hasStart?[r.startDate,r.endDate]:[])].map(q).join(','))});
  lines.push(['','','Total',g.total].map(q).join(','));ptSave(new Blob(['﻿'+lines.join('\r\n')],{type:'text/csv'}),`Schedule - ${String(b.name||'estimate').replace(/[\\/:*?"<>|]+/g,' ').trim()}.csv`)}
document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t)return;const a=t.dataset.act;if(!a.startsWith('gt-')||!S.est||!S.est.data)return;const d=S.est.data;
  switch(a){
    case 'gt-reset':if(EC().ro)break;ganttData(d).rows={};estTouch();render();toast('Schedule reset to the estimate');break;
    case 'gt-useind':{if(EC().ro)break;const g=ganttCalc(d);d.settings.durDays=g.total;estTouch();render();toast(`Indirects now use ${g.total} working days`);break}
    case 'gt-csv':ganttCsv(d);break;
    case 'gt-print':{const b=byId(S.bids,S.est.bidId);const g=ganttCalc(d);const old=document.title;document.title=`Schedule - ${b?.name||''}`;const pr=document.createElement('div');pr.id='print-root';pr.className='gt-print';
      pr.innerHTML=`<h1>${esc(b?.name||'')}</h1><p>Schedule · ${ganttWeeksText(g)}${g.hasStart?` · ${fmtDate(g.startDate)} to ${fmtDate(g.finishDate)}`:''}</p>`+($('#gt-paper')?.outerHTML.replace('id="gt-paper"','')||'');pr.querySelectorAll('input,select').forEach(el=>{const s=document.createElement('span');s.textContent=el.tagName==='SELECT'?(el.selectedOptions[0]?.textContent||''):(el.value||el.placeholder||'');el.replaceWith(s)});
      document.body.appendChild(pr);document.body.classList.add('printing-prop');window.print();setTimeout(()=>{document.body.classList.remove('printing-prop');pr.remove();document.title=old},500);break}
  }});
document.addEventListener('change',e=>{const t=e.target;if(!S.est||!S.est.data||EC().ro)return;const d=S.est.data;const row=id=>{const G=ganttData(d);return G.rows[id]=G.rows[id]||{}};
  if(t.dataset.gs!=null){ganttData(d).start=t.value||'';estTouch();render();return}
  if(t.dataset.gd){const v=t.value.trim();const r=row(t.dataset.gd);if(v===''||isNaN(+v))delete r.dur;else r.dur=Math.max(0,Math.round(+v));estTouch();render();return}
  if(t.dataset.gl){const v=t.value.trim();const r=row(t.dataset.gl);if(v===''||isNaN(+v)||!+v)delete r.lag;else r.lag=Math.round(+v);estTouch();render();return}
  if(t.dataset.gp){const r=row(t.dataset.gp);if(t.value)r.pred=t.value;else delete r.pred;estTouch();render();return}});

/* =====================================================================
   Change orders: priced, tracked and printed from the job.
   PMs (anyone who can edit jobs) write them. Approving one adds a
   change-order line to the job's budget and schedule of values.
   ===================================================================== */
S.change_orders=[];S.coMissing=false;
const CX_SQL='Change orders need a one-time database update (update-25-change-orders.sql).';
const CX_STATUS=['Draft','Sent','Approved','Rejected','Void'];const CX_CLS={Draft:'',Sent:'warn',Approved:'good',Rejected:'bad',Void:''};
const CX_REASONS=['Owner / GC request','Plan revision','RFI response','Field condition','Unsuitable soils / rock','Quantity overrun','Schedule / acceleration','Credit / deduct','Other'];
const CX_KINDS=[['labor','Labor'],['equipment','Equipment'],['material','Material'],['sub','Subcontract'],['trucking','Trucking'],['other','Other'],['bid','Contract unit price']];
async function loadCOs(){if(!sb||!(can('jobs')||can('acct')))return;const {data,error}=await sb.from('change_orders').select('*');if(error){S.coMissing=true;S.change_orders=[];return}S.coMissing=false;S.change_orders=data||[];schedule()}
const jobCOs=jobId=>(S.change_orders||[]).filter(c=>c.job_id===jobId).sort((a,b)=>String(a.number).localeCompare(String(b.number),undefined,{numeric:true}));
const cxD=c=>{const d=c.data&&typeof c.data==='object'?c.data:{};if(!Array.isArray(d.lines))d.lines=[];d.mk=d.mk&&typeof d.mk==='object'?d.mk:{};return d};
function cxCalc(c){const d=cxD(c);const job=jobOf(c.job_id)||{};const by={labor:0,equipment:0,material:0,sub:0,trucking:0,other:0,bid:0};
  d.lines.forEach(l=>{const k=by[l.kind]!=null?l.kind:'other';by[k]+=(num(l.qty)||0)*(num(l.price)||0)});
  const self=by.labor+by.equipment+by.material+by.trucking+by.other,sub=by.sub;const ps=num(d.mk.self)||0,pb=num(d.mk.sub)||0,pbond=num(d.mk.bond)||0;
  const mkSelf=self*ps/100,mkSub=sub*pb/100;const before=self+mkSelf+sub+mkSub+by.bid;const bond=before*pbond/100;const total=before+bond;
  const jf=(1+(num(job.overhead_pct)||0)/100)*(1+(num(job.markup_pct)||0)/100);const bidCost=by.bid/(jf||1);
  return {by,self,sub,mkSelf,mkSub,bond,before,total:r2(total),cost:r2(self+sub+bidCost),bidCost,ps,pb,pbond}}
function cxExposure(jobId){const o={Approved:0,Sent:0,Draft:0,n:0,days:0};jobCOs(jobId).forEach(c=>{if(o[c.status]!=null){o[c.status]+=num(c.price)||0;o.n++}if(c.status==='Approved')o.days+=num(c.days)||0});return o}
function cxNew(jobId){const cs=jobCOs(jobId);const last=cs[cs.length-1];const n=Math.max(0,...cs.map(c=>parseInt(c.number,10)||0),...jobItems(jobId).map(i=>parseInt(i.change_order,10)||0))+1;const mk=last?cxD(last).mk:{};
  return {id:newId(),job_id:jobId,number:String(n),title:'',description:'',reason:CX_REASONS[0],status:'Draft',days:null,_new:true,data:{lines:[cxLine('labor')],mk:{self:mk.self??15,sub:mk.sub??10,bond:mk.bond??0},notes:'',detail:true}}}
const cxLine=k=>({id:newId(),kind:k||'material',desc:'',qty:null,unit:'',price:null});
function cxTab(job){const cs=jobCOs(job.id);const X=cxExposure(job.id);const C=jobContract(job);const edit=canJob();
  if(S.coMissing)return `<div class="notice">${CX_SQL}</div>`;
  return `<div class="statline cx-stat"><div><b>${money(C.contract-C.co)}</b>Original contract</div><div><b>${money(X.Approved)}</b>Approved change orders</div><div><b>${money(X.Sent)}</b>Sent, waiting on approval</div><div><b>${money(X.Draft)}</b>Drafts</div><div><b>${money(C.contract-C.co+X.Approved)}</b>Revised contract</div>${X.days?`<div><b>${X.days}</b>Days added</div>`:''}</div>
  <div class="bar"><span class="small dim">${cs.length} change order${cs.length===1?'':'s'}</span><span style="flex:1"></span>${edit?'<button class="btn primary" data-act="cx-new">+ Change order</button>':''}</div>
  <div class="panel scroll"><table><thead><tr><th>CO #</th><th>Title</th><th>Reason</th><th>Status</th><th class="r">Days</th><th class="r">Cost</th><th class="r">Price</th><th>Sent</th><th>Approved</th></tr></thead><tbody>
  ${cs.map(c=>`<tr class="click" data-act="cx-open" data-id="${c.id}"><td><b>${esc(c.number)}</b></td><td class="proj">${esc(c.title||'Untitled')}</td><td class="small">${esc(c.reason||'')}</td><td>${pill(c.status,CX_CLS[c.status])}</td><td class="r num">${c.days||''}</td><td class="r num">${money(c.cost)}</td><td class="r num"><b>${money(c.price)}</b></td><td class="small">${c.sent_date?fmtShort(c.sent_date):''}</td><td class="small">${c.approved_date?fmtShort(c.approved_date):''}${c.approved_by?`<br><span class="dim">${esc(c.approved_by)}</span>`:''}</td></tr>`).join('')
    ||`<tr><td colspan="9"><div class="empty"><b>No change orders yet</b>${edit?'Click <b>+ Change order</b> to price extra work, a credit, or a quantity change.':''}</div></td></tr>`}</tbody></table></div>
  <p class="hint">Approving a change order adds it to this job’s budget and schedule of values, so it shows on pay applications. Work done on Sent or Draft change orders isn’t in the contract yet.</p>`}
function cxTotHtml(c){const R=cxCalc(c);const ln=(l,v,cls)=>`<div class="cx-tl${cls?' '+cls:''}"><span>${l}</span><b>${money2(v)}</b></div>`;
  return `${ln('Self-performed cost',R.self)}${R.ps?ln(`Markup ${fmtN(R.ps,1)}%`,R.mkSelf):''}${R.sub||R.pb?ln('Subcontract cost',R.sub):''}${R.sub&&R.pb?ln(`Markup on subs ${fmtN(R.pb,1)}%`,R.mkSub):''}${R.by.bid?ln('Work at contract unit prices',R.by.bid):''}${R.pbond?ln(`Bond / insurance ${fmtN(R.pbond,2)}%`,R.bond):''}${ln(R.total<0?'Credit':'Change order total',R.total,'cx-grand')}`}
function cxModal(){const c=M.draft;const d=cxD(c);const job=jobOf(c.job_id);const lock=!canJob()||c.status==='Approved'||c.status==='Void';const dis=lock?' disabled':'';
  const items=jobItems(c.job_id).filter(i=>!i.change_order&&num(i.quantity)>0&&num(i.bid_price)!=null);
  const cbs=S.codebook.filter(x=>['material','labor','equipment'].includes(x.book)&&x.active!==false).slice(0,1500);
  const rows=d.lines.map((l,i)=>`<tr><td><select class="field cx-k" data-cxl="${i}.kind"${dis}>${CX_KINDS.map(([k,n])=>`<option value="${k}"${l.kind===k?' selected':''}>${n}</option>`).join('')}</select></td>
    <td><input class="field" id="cxd-${l.id}" data-cxl="${i}.desc" list="cx-cbl" value="${esc(l.desc||'')}" placeholder="${l.kind==='bid'?'Contract item':'Type, or pick from the codebook'}"${dis}></td>
    <td><input class="field num cx-n" id="cxq-${l.id}" data-cxl="${i}.qty" inputmode="decimal" value="${l.qty??''}" placeholder="0"${dis}></td><td><input class="field cx-u" id="cxu-${l.id}" data-cxl="${i}.unit" list="cb-units" value="${esc(l.unit||'')}"${dis}></td>
    <td><input class="field num cx-n" id="cxp-${l.id}" data-cxl="${i}.price" inputmode="decimal" value="${l.price??''}" placeholder="0.00"${dis}></td><td class="r num" id="cxt-${l.id}">${money2((num(l.qty)||0)*(num(l.price)||0))}</td><td>${lock?'':`<button class="x" data-act="cx-rm" data-i="${i}" aria-label="Remove line">×</button>`}</td></tr>`).join('');
  return mhead(c._new?'New change order':`Change order ${c.number}`,jobLabel(job))+`<div class="mbody">
    ${c.status==='Approved'?`<div class="notice">Approved${c.approved_date?' '+fmtShort(c.approved_date):''}${c.approved_by?' by '+esc(c.approved_by):''}. It’s in the job’s budget and schedule of values, so it’s locked. To change the amount, write another change order.</div>`:''}
    <fieldset><legend>What changed</legend><div class="fg"><label class="f">CO number<input class="field" id="cx-no" data-cx="number" value="${esc(c.number)}"${dis}></label><label class="f s2">Title<input class="field" id="cx-title" data-cx="title" value="${esc(c.title||'')}" placeholder="e.g. Added storm line at Building C"${dis}></label>
      <label class="f">Reason<select class="field" data-cx="reason"${dis}>${[...new Set([...CX_REASONS,c.reason].filter(Boolean))].map(r=>`<option${c.reason===r?' selected':''}>${esc(r)}</option>`).join('')}</select></label>
      <label class="f s3">Description of the work<textarea class="field" id="cx-desc" data-cx="description" rows="3" placeholder="What is being added, removed or changed, and where. Reference the RFI, directive or plan sheet."${dis}>${esc(c.description||'')}</textarea></label>
      <label class="f">Days added to the schedule<input class="field num" id="cx-days" data-cx="days" inputmode="numeric" value="${c.days??''}" placeholder="0"${dis}></label></div></fieldset>
    <fieldset><legend>Pricing</legend><datalist id="cx-cbl">${cbs.map(x=>`<option value="${esc(x.description)}">${esc([x.code,x.unit,cbCost(x)!=null?money2(cbCost(x)):''].filter(Boolean).join(' · '))}</option>`).join('')}</datalist>
      <div class="scroll"><table class="cx-t"><thead><tr><th>Type</th><th>Description</th><th class="r">Qty</th><th>Unit</th><th class="r">Unit cost</th><th class="r">Total</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="dim small">No lines yet.</td></tr>'}</tbody></table></div>
      ${lock?'':`<div class="adders"><button class="btn sm" data-act="cx-add">+ Line</button>${items.length?`<select class="field cx-from" data-cxfrom aria-label="Add from a contract item"><option value="">+ From a contract item…</option>${items.map(i=>`<option value="${i.id}">${esc((i.code?i.code+' ':'')+i.description).slice(0,70)} — ${money2(num(i.bid_price)/num(i.quantity))}/${esc(i.unit||'unit')}</option>`).join('')}</select>`:''}</div>`}
      <div class="cx-bot"><div class="fg cx-mk"><label class="f">Markup on your work %<input class="field num" id="cx-ms" data-cxm="self" inputmode="decimal" value="${d.mk.self??''}"${dis}></label><label class="f">Markup on subs %<input class="field num" id="cx-mb" data-cxm="sub" inputmode="decimal" value="${d.mk.sub??''}"${dis}></label><label class="f">Bond / insurance %<input class="field num" id="cx-mo" data-cxm="bond" inputmode="decimal" value="${d.mk.bond??''}"${dis}></label>
        <p class="hint s3">Use a negative quantity for a credit. Lines at contract unit prices are not marked up again. Markups carry over to the next change order on this job.</p></div><div class="cx-tot" id="cx-tot">${cxTotHtml(c)}</div></div></fieldset>
    <fieldset><legend>On the printed change order</legend><label class="check small"><input type="checkbox" data-cxb="detail"${d.detail!==false?' checked':''}${dis}> Show every pricing line (otherwise totals by type)</label>
      <label class="f">Notes, exclusions and conditions<textarea class="field" id="cx-notes" data-cxn rows="2" placeholder="e.g. Price valid 15 days. Excludes rock, testing and survey."${dis}>${esc(d.notes||'')}</textarea></label></fieldset></div>
  <div class="mfoot"><div>${!c._new&&canJob()&&c.status!=='Approved'?`<button class="btn danger${M.arm2?' arm':''}" data-act="cx-del">${M.arm2?'Click again to delete':'Delete'}</button>`:''}</div><div class="r"><button class="btn" data-act="close">Close</button><button class="btn" data-act="cx-print">Print / PDF</button>
    ${lock?'':`<button class="btn" data-act="cx-save">Save</button>${c.status==='Draft'||c.status==='Rejected'?'<button class="btn" data-act="cx-status" data-v="Sent">Save &amp; mark sent</button>':''}${c.status==='Sent'?'<button class="btn" data-act="cx-status" data-v="Rejected">Rejected</button>':''}<button class="btn primary" data-act="cx-status" data-v="Approved">${M.armA?'Click again — adds it to the contract':'Approved'}</button>`}</div></div>`}
function cxRow(c){const R=cxCalc(c);const d=cxD(c);return {id:c.id,job_id:c.job_id,number:String(c.number||'').trim(),title:String(c.title||'').trim(),description:String(c.description||'').trim(),reason:c.reason||'',status:c.status||'Draft',days:num(c.days)!=null?Math.round(num(c.days)):null,
  data:{lines:d.lines.filter(l=>String(l.desc||'').trim()||num(l.qty)||num(l.price)),mk:d.mk,notes:d.notes||'',detail:d.detail!==false},cost:R.cost,price:R.total,sent_date:c.sent_date||null,approved_date:c.approved_date||null,approved_by:c.approved_by||'',job_item_id:c.job_item_id||null,updated_by_name:myName()}}
async function cxSave(status){const c=M.draft;if(!canJob())return false;if(!String(c.title||'').trim()){toast('Give the change order a title.');return false}if(!String(c.number||'').trim()){toast('Give it a CO number.');return false}
  if(jobCOs(c.job_id).some(x=>x.id!==c.id&&String(x.number).trim()===String(c.number).trim())){toast(`CO ${c.number} already exists on this job.`);return false}
  const row=cxRow(c);const R=cxCalc(c);
  try{if(status==='Sent'){row.status='Sent';row.sent_date=row.sent_date||todayStr()}
    if(status==='Rejected')row.status='Rejected';
    if(status==='Approved'){if(!row.data.lines.length){toast('Add at least one pricing line first.');return false}const who=prompt('Who approved it? (name at the GC or owner, optional)','');if(who===null)return false;
      const by=R.by;const n=jobItems(c.job_id);const cost=R.cost;const jid=newId();
      await run(sb.from('job_items').insert({id:jid,job_id:c.job_id,code:'CO'+row.number,description:row.title,unit:'LS',quantity:null,labor:r2(by.labor),equipment:r2(by.equipment),materials:r2(by.material),subcontract:r2(by.sub),other:r2(by.trucking+by.other+R.bidCost),overhead_pct:0,
        markup_pct:cost?Math.max(-999,Math.min(9999,Math.round((R.total/cost-1)*1e5)/1e3)):0,bid_price:R.total,change_order:row.number,sort:n.reduce((m,i)=>Math.max(m,i.sort||0),0)+1,notes:'Change order'}));
      row.status='Approved';row.approved_date=todayStr();row.approved_by=String(who).trim();row.job_item_id=jid;row.sent_date=row.sent_date||todayStr()}
    if(c._new)await run(sb.from('change_orders').insert(row));else await run(sb.from('change_orders').update(row).eq('id',c.id));
    await Promise.all([loadCOs(),status==='Approved'?loadTable('job_items'):null]);const nc=(S.change_orders||[]).find(x=>x.id===c.id);if(nc){M.draft=clone(nc);M.arm2=M.armA=false;renderModal()}render();
    toast(status==='Approved'?`CO ${row.number} approved — ${money(R.total)} added to the contract`:status==='Sent'?`CO ${row.number} marked sent`:status==='Rejected'?`CO ${row.number} marked rejected`:'Saved');return true}
  catch(e){toast(/change_orders|does not exist|schema cache/i.test(errMsg(e))?CX_SQL:errMsg(e));return false}}
function cxPrint(c){const job=jobOf(c.job_id)||{};const d=cxD(c);const R=cxCalc(c);const cl=jobClient(job);const co=S.settings.general?.companyName||CFG.companyName||'';const logo=BRAND.loginLogo||'';const L=propLib();const C=jobContract(job);
  const prior=jobCOs(c.job_id).filter(x=>x.status==='Approved'&&x.id!==c.id).reduce((s,x)=>s+(num(x.price)||0),0);const orig=C.contract-C.co;const KN=Object.fromEntries(CX_KINDS);
  const lines=d.lines.filter(l=>String(l.desc||'').trim()||num(l.qty)||num(l.price));
  const table=d.detail!==false?`<table class="pp-t"><thead><tr><th>Type</th><th>Description</th><th class="r">Qty</th><th>Unit</th><th class="r">Unit price</th><th class="r">Amount</th></tr></thead><tbody>${lines.map(l=>`<tr><td>${esc(KN[l.kind]||'Other')}</td><td>${esc(l.desc||'')}</td><td class="r">${qtyFmt(num(l.qty)||0)}</td><td>${esc(l.unit||'')}</td><td class="r">${money2(num(l.price)||0)}</td><td class="r">${money2((num(l.qty)||0)*(num(l.price)||0))}</td></tr>`).join('')}</tbody></table>`
    :`<table class="pp-t"><thead><tr><th>Type</th><th class="r">Amount</th></tr></thead><tbody>${CX_KINDS.filter(([k])=>R.by[k]).map(([k,n])=>`<tr><td>${n}</td><td class="r">${money2(R.by[k])}</td></tr>`).join('')}</tbody></table>`;
  const tl=(l,v,g)=>`<tr${g?' class="pp-grand"':''}><td>${l}</td><td class="r">${money2(v)}</td></tr>`;
  const html=`<div class="pp"><div class="pp-head">${logo?`<img src="${esc(logo)}" alt="" class="pp-logo">`:`<div class="pp-co">${esc(co)}</div>`}<div class="pp-lh">${propLines(L.letterhead).map(esc).join('<br>')}</div></div>
    <h1 class="pp-title">Change Order Request ${esc(c.number||'')}</h1>
    <div class="pp-meta"><div><span>Project</span><b>${esc(job.name||'')}</b>${job.location?`<div>${esc(job.location)}</div>`:''}</div><div><span>Date</span><b>${fmtDate(c.sent_date||todayStr())}</b></div><div><span>To</span><b>${esc(cl?.company||'—')}</b></div><div><span>Job #</span><b>${esc(job.job_number||'—')}</b></div></div>
    <h2>${esc(c.title||'Change order')}</h2>${c.reason?`<p class="pp-basis"><b>Reason:</b> ${esc(c.reason)}</p>`:''}${propLines(c.description).map(x=>`<p>${esc(x)}</p>`).join('')}
    <h2>Pricing</h2>${table}<table class="pp-t" style="margin-top:8px"><tbody>${R.self?tl('Self-performed work',R.self):''}${R.mkSelf?tl(`Markup ${fmtN(R.ps,1)}%`,R.mkSelf):''}${R.sub?tl('Subcontract work',R.sub):''}${R.mkSub?tl(`Markup on subcontract ${fmtN(R.pb,1)}%`,R.mkSub):''}${R.by.bid?tl('Work at contract unit prices',R.by.bid):''}${R.bond?tl(`Bond / insurance ${fmtN(R.pbond,2)}%`,R.bond):''}${tl(R.total<0?'Total credit':'Total this change order',R.total,1)}</tbody></table>
    <h2>Contract summary</h2><table class="pp-t"><tbody>${tl('Original contract',orig)}${tl('Previously approved change orders',prior)}${tl('This change order',R.total)}${tl('Revised contract',orig+prior+R.total,1)}</tbody></table>
    ${num(c.days)?`<p class="pp-basis"><b>Schedule:</b> ${Math.round(num(c.days))} working day${Math.round(num(c.days))===1?'':'s'} added to the contract time.</p>`:''}
    ${propLines(d.notes).length?`<h2>Notes</h2><ul>${propLines(d.notes).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}
    <div class="pa-sign"><div>${esc(co)} / date</div><div>Approved by / date</div></div></div>`;
  const old=document.title;document.title=`CO ${c.number} - ${job.name||''}`;const pr=document.createElement('div');pr.id='print-root';pr.innerHTML=html;document.body.appendChild(pr);document.body.classList.add('printing-prop');window.print();setTimeout(()=>{document.body.classList.remove('printing-prop');pr.remove();document.title=old},500)}
FOCUS_ATTRS.push('data-cx','data-cxl','data-cxm','data-cxn');
document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t||t.tagName==='SELECT')return;const a=t.dataset.act;if(!a.startsWith('cx-'))return;
  switch(a){
    case 'cx-new':if(canJob()){M={kind:'cx',draft:cxNew(S.jobId)};showModal();setTimeout(()=>$('#cx-title')?.focus(),0)}break;
    case 'cx-open':{const c=(S.change_orders||[]).find(x=>x.id===t.dataset.id);if(c){M={kind:'cx',draft:clone(c)};cxD(M.draft);showModal()}break}
    case 'cx-add':cxD(M.draft).lines.push(cxLine('material'));renderModal();break;
    case 'cx-rm':cxD(M.draft).lines.splice(+t.dataset.i,1);renderModal();break;
    case 'cx-save':cxSave();break;
    case 'cx-status':{const v=t.dataset.v;if(v==='Approved'&&!M.armA){M.armA=true;renderModal();break}cxSave(v);break}
    case 'cx-print':cxPrint(M.draft);break;
    case 'cx-del':{if(!M.arm2){M.arm2=true;renderModal();break}const id=M.draft.id;run(sb.from('change_orders').delete().eq('id',id)).then(loadCOs).then(()=>{closeModal();render();toast('Change order deleted')}).catch(er=>toast(errMsg(er)));break}
  }});
document.addEventListener('input',e=>{const t=e.target;if(!M||M.kind!=='cx')return;const c=M.draft;const d=cxD(c);
  if(t.dataset.cx&&t.tagName!=='SELECT'){c[t.dataset.cx]=t.value;return}
  if(t.dataset.cxn!=null){d.notes=t.value;return}
  if(t.dataset.cxm){d.mk[t.dataset.cxm]=t.value===''?null:num(t.value);const el=$('#cx-tot');if(el)el.innerHTML=cxTotHtml(c);return}
  if(t.dataset.cxl&&t.tagName!=='SELECT'){const [i,k]=t.dataset.cxl.split('.');const l=d.lines[+i];if(!l)return;l[k]=k==='qty'||k==='price'?(t.value===''?null:num(t.value)):t.value;
    const tc=$('#cxt-'+l.id);if(tc)tc.textContent=money2((num(l.qty)||0)*(num(l.price)||0));const el=$('#cx-tot');if(el)el.innerHTML=cxTotHtml(c)}});
document.addEventListener('change',e=>{const t=e.target;if(!M||M.kind!=='cx')return;const c=M.draft;const d=cxD(c);
  if(t.dataset.cx&&t.tagName==='SELECT'){c[t.dataset.cx]=t.value;return}
  if(t.dataset.cxb){d[t.dataset.cxb]=t.checked;return}
  if(t.dataset.cxfrom!=null){const it=byId(S.job_items,t.value);if(it){d.lines.push({id:newId(),kind:'bid',desc:(it.code?it.code+' ':'')+it.description,qty:null,unit:it.unit||'',price:r2(num(it.bid_price)/num(it.quantity)),item:it.id});renderModal();setTimeout(()=>$('#cxq-'+d.lines[d.lines.length-1].id)?.focus(),0)}return}
  if(t.dataset.cxl){const [i,k]=t.dataset.cxl.split('.');const l=d.lines[+i];if(!l)return;
    if(k==='kind'){l.kind=t.value;renderModal();return}
    if(k==='desc'){const x=S.codebook.find(o=>['material','labor','equipment'].includes(o.book)&&o.description===t.value);if(x){l.kind=x.book==='material'?resKindOf(x):x.book;if(!l.unit)l.unit=x.book==='material'?(x.unit||''):'HR';if(l.price==null&&cbCost(x)!=null)l.price=+cbCost(x).toFixed(2);renderModal()}}}});

/* =====================================================================
   Accounts: admins create and manage logins from the Team page.
   No secret key lives in the app. A new login is made through the normal
   sign-up path on a throwaway connection (so the admin stays signed in),
   then database functions that only admins can run finish the job.
   ===================================================================== */
S.acctInfo=null;
const ACCT_SQL='Managing accounts from the app needs a one-time database update (update-26-accounts.sql).';
const acctErr=e=>{const m=errMsg(e);return /admin_|function .* does not exist|schema cache|PGRST202/i.test(m)?ACCT_SQL:/signups? (are )?(not allowed|disabled)/i.test(m)?'New sign-ups are switched off in Supabase. Turn on “Allow new users to sign up” (Authentication → Sign In / Providers), then try again. New people still can’t see anything until you give them a role.':/already registered|already been registered|user_already_exists/i.test(m)?'There’s already a login with that email.':/rate limit/i.test(m)?'Too many new accounts in a short time. Wait a few minutes and try again.':m};
function tempPassword(){const A='ABCDEFGHJKMNPQRSTUVWXYZ',a='abcdefghijkmnpqrstuvwxyz',n='23456789';const r=new Uint32Array(12);crypto.getRandomValues(r);const pick=(s,i)=>s[r[i]%s.length];
  return pick(A,0)+pick(a,1)+pick(a,2)+pick(a,3)+pick(n,4)+pick(n,5)+pick(A,6)+pick(a,7)+pick(a,8)+pick(n,9)+pick(n,10)+pick(A,11)}
async function loadAcctInfo(){if(!sb||!isAdmin())return;const {data,error}=await sb.rpc('admin_user_list');if(error){S.acctInfo=null;return}S.acctInfo=new Map((data||[]).map(u=>[u.id,u]));schedule();if(M&&M.kind==='access')renderModal()}
function userAddModal(){const x=M;const done=x.done;
  if(done)return mhead('Account created',done.email)+`<div class="mbody"><div class="notice"><b>${esc(done.name||done.email)}</b> can sign in now as <b>${esc(ROLE_LABEL[done.role]||done.role)}</b>.</div>
    <fieldset><legend>Give them these</legend><div class="ua-cred"><div><span>Website</span><b>${esc(location.origin+location.pathname)}</b></div><div><span>Email</span><b>${esc(done.email)}</b></div><div><span>Temporary password</span><b class="ua-pw">${esc(done.pw)}</b></div></div>
      <div class="adders"><button class="btn sm" data-act="ua-copy">Copy to clipboard</button></div><p class="hint">This password isn’t shown again. The first time they sign in, the app makes them choose their own password before they can do anything else.</p></fieldset></div>
    <div class="mfoot"><div></div><div class="r"><button class="btn" data-act="ua-again">Add another</button><button class="btn primary" data-act="close">Done</button></div></div>`;
  return mhead('Add a person','Creates their login and sets what they can open')+`<div class="mbody"><div class="fg">
    <label class="f s2">Name<input class="field" id="ua-name" data-ua="name" value="${esc(x.name)}" placeholder="First and last name"></label><label class="f s2">Email<input class="field" id="ua-email" data-ua="email" type="email" value="${esc(x.email)}" placeholder="name@company.com" autocomplete="off"></label>
    <label class="f s2">Role<select class="field" data-ua="role">${ROLE_ORDER.filter(r=>r!=='pending').map(r=>`<option value="${r}"${x.role===r?' selected':''}>${esc(ROLE_LABEL[r]||r)}</option>`).join('')}</select></label><label class="f s2">Title <span class="dim">(optional)</span><input class="field" id="ua-title" data-ua="title" value="${esc(x.title)}"></label>
    <label class="f s2">Temporary password<input class="field" id="ua-pw" data-ua="pw" value="${esc(x.pw)}" autocomplete="off"></label><div class="f s2" style="justify-content:flex-end"><button class="btn sm" data-act="ua-gen">Make a new one</button></div></div>
    <p class="hint">${esc(ROLE_ABOUT[x.role]||'')}</p>${x.role==='estimator'?'<p class="hint">Estimators also need an estimator record linked to their login before bids can be assigned to them (Team → Estimators).</p>':''}</div>
  <div class="mfoot"><div></div><div class="r"><button class="btn" data-act="close">Cancel</button><button class="btn primary" data-act="ua-create"${x.busy?' disabled':''}>${x.busy?'Creating…':'Create account'}</button></div></div>`}
async function userCreate(){const x=M;if(!isAdmin()||x.busy)return;const email=String(x.email||'').trim().toLowerCase(),name=String(x.name||'').trim(),pw=String(x.pw||'');
  if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){toast('Enter their email address.');return}if(!name){toast('Enter their name.');return}if(pw.length<8){toast('The password needs at least 8 characters.');return}
  if(S.profiles.some(p=>String(p.email||'').toLowerCase()===email)){toast('There’s already a login with that email.');return}
  x.busy=true;renderModal();
  try{const tmp=window.supabase.createClient(CFG.supabaseUrl,CFG.supabaseAnonKey,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false,storageKey:'bp-new-account'}});
    const {data,error}=await tmp.auth.signUp({email,password:pw,options:{data:{full_name:name}}});if(error)throw error;const u=data&&data.user;if(!u||!u.id||(Array.isArray(u.identities)&&!u.identities.length))throw new Error('There’s already a login with that email.');
    try{await tmp.auth.signOut()}catch(e){}
    await run(sb.rpc('admin_finish_user',{p_id:u.id,p_name:name,p_role:x.role,p_title:String(x.title||'').trim()}));await Promise.all([loadProfiles(),loadAcctInfo()]);
    M={kind:'useradd',done:{email,name,role:x.role,pw}};renderModal();render()}
  catch(e){x.busy=false;renderModal();toast(acctErr(e))}}
function acctBox(d){if(!isAdmin())return '';const self=d.id===S.session.user.id;const u=S.acctInfo&&S.acctInfo.get(d.id);const off=u&&u.banned;const x=M;
  return `<fieldset><legend>Login</legend>${S.acctInfo?`<p class="small" style="margin:0 0 8px">${esc(d.email||'')} · ${off?'<b class="bad-t">Deactivated</b>':u&&!u.confirmed?'<b class="warn-t">Email not confirmed</b>':'Active'}${u&&u.last_sign_in_at?' · last signed in '+fmtShort(String(u.last_sign_in_at).slice(0,10)):u?' · has never signed in':''}</p>`:`<p class="hint">${ACCT_SQL}</p>`}
    <div class="adders" style="margin:0"><button class="btn sm" data-act="ua-reset">Email a password reset link</button><button class="btn sm" data-act="ua-setpw">Set a temporary password</button>${u&&!u.confirmed?'<button class="btn sm" data-act="ua-confirm">Confirm their email</button>':''}
      ${self||d.is_dev?'':`<button class="btn sm" data-act="ua-active" data-v="${off?1:0}">${off?'Reactivate':'Deactivate'}</button><button class="btn sm danger${x.armDel?' arm':''}" data-act="ua-del">${x.armDel?'Click again — this can’t be undone':'Delete account'}</button>`}</div>
    ${x.newPw?`<div class="notice" style="margin-top:10px">New temporary password: <b class="ua-pw">${esc(x.newPw)}</b> — it isn’t shown again.</div>`:''}
    ${self||d.is_dev?'':'<p class="hint">Deactivate blocks sign-in and removes their access but keeps the account and everything they did. Delete removes the login for good; their bids, notes and history stay.</p>'}</fieldset>`}
FOCUS_ATTRS.push('data-ua');
document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t||t.tagName==='SELECT')return;const a=t.dataset.act;if(!a.startsWith('ua-')||!isAdmin())return;const d=M&&M.kind==='access'?M.draft:null;
  const after=()=>Promise.all([loadProfiles(),loadAcctInfo()]).then(()=>{render()});
  switch(a){
    case 'ua-new':case 'ua-again':M={kind:'useradd',name:'',email:'',role:'estimator',title:'',pw:tempPassword()};showModal();setTimeout(()=>$('#ua-name')?.focus(),0);break;
    case 'ua-gen':M.pw=tempPassword();renderModal();break;
    case 'ua-create':userCreate();break;
    case 'ua-copy':{const x=M.done;const txt=`${APP_NAME||'Bid pipeline'}\n${location.origin+location.pathname}\nEmail: ${x.email}\nTemporary password: ${x.pw}`;(navigator.clipboard?navigator.clipboard.writeText(txt):Promise.reject()).then(()=>toast('Copied')).catch(()=>toast('Couldn’t copy — select the text and copy it by hand.'));break}
    case 'ua-reset':if(d)sb.auth.resetPasswordForEmail(d.email,{redirectTo:location.origin+location.pathname}).then(({error})=>toast(error?acctErr(error):`Reset link sent to ${d.email}`));break;
    case 'ua-setpw':{if(!d)break;const pw=prompt('Temporary password (at least 8 characters)',tempPassword());if(pw===null)break;if(String(pw).length<8){toast('The password needs at least 8 characters.');break}
      run(sb.rpc('admin_set_password',{p_id:d.id,p_password:String(pw)})).then(()=>{M.newPw=String(pw);renderModal();toast('Password changed. They’ll choose their own at next sign-in.')}).catch(er=>toast(acctErr(er)));break}
    case 'ua-confirm':if(d)run(sb.rpc('admin_finish_user',{p_id:d.id,p_name:null,p_role:null,p_title:null})).then(after).then(()=>toast('Email confirmed')).catch(er=>toast(acctErr(er)));break;
    case 'ua-active':{if(!d)break;const on=t.dataset.v==='1';run(sb.rpc('admin_set_active',{p_id:d.id,p_active:on})).then(after).then(()=>{const p=S.profiles.find(x=>x.id===d.id);if(p&&M&&M.kind==='access'){M.draft.role=p.role;renderModal()}toast(on?'Reactivated — now pick their role and save':'Deactivated. They can’t sign in.')}).catch(er=>toast(acctErr(er)));break}
    case 'ua-del':{if(!d)break;if(!M.armDel){M.armDel=true;renderModal();break}run(sb.rpc('admin_delete_user',{p_id:d.id})).then(()=>{closeModal();return after()}).then(()=>toast('Account deleted')).catch(er=>{M.armDel=false;renderModal();toast(acctErr(er))});break}
  }});
document.addEventListener('input',e=>{const t=e.target;if(M&&M.kind==='useradd'&&t.dataset.ua&&t.tagName!=='SELECT')M[t.dataset.ua]=t.value});
document.addEventListener('change',e=>{const t=e.target;if(M&&M.kind==='useradd'&&t.dataset.ua&&t.tagName==='SELECT'){M[t.dataset.ua]=t.value;renderModal()}});

/* =====================================================================
   Client bid tracker: one private link per GC / client. Opening it
   (no login) shows every project they've sent and the stage each bid
   is in. Prices, other GCs and notes never leave the database.
   ===================================================================== */
const TRACK_SQL='The client tracker needs a one-time database update (update-28-client-tracker.sql).';
const TRACK_STEPS=[['Received','We have your invitation'],['Estimating','Takeoff and pricing under way'],['Final review','Numbers are being checked'],['Proposal sent','Our proposal is in your hands'],['Decision','Award decision']];
const trackUrl=tk=>location.origin+location.pathname+'?track='+tk;
function trackStage(b){if(b.status==='No Bid')return {n:0,note:'We’re not able to bid this one',cls:'off'};
  if(b.status==='Awarded')return {n:5,note:b.awarded_to_you?'Awarded to us — thank you!':'Closed',cls:b.awarded_to_you?'win':'done'};
  if(b.status==='Not Awarded')return {n:5,note:'Closed',cls:'done'};
  if(b.sent)return {n:4,note:b.sent_date?'Sent '+fmtShort(b.sent_date):'Proposal sent'};
  if(b.status==='Proposal Review')return {n:3};if(['RFQ Sent','Takeoff','Quotes Received','Estimating','Takeoff Complete'].includes(b.status))return {n:2};
  if(b.status==='On Hold')return {n:2,note:'On hold',cls:'hold'};return {n:1}}
function trackCard(b){const st=trackStage(b);const e=b.estimator;const ad=b.addenda||[];const late=b.due_date&&!b.sent&&st.n<4&&st.n>0&&daysUntil(b.due_date)<0;
  const steps=st.n?`<ol class="ct-steps${st.cls?' '+st.cls:''}" aria-label="Stage ${st.n} of 5: ${TRACK_STEPS[st.n-1][0]}">${TRACK_STEPS.map(([l],i)=>`<li class="${i+1<st.n?'past':i+1===st.n?'now':''}"><span class="ct-dot">${i+1<st.n||(st.n===5&&i===4)?'✓':i+1}</span><span class="ct-lab">${l}</span></li>`).join('')}</ol>`:'';
  return `<article class="ct-card"><header><div><h2>${esc(b.name)}</h2>${b.location?`<p>${esc(b.location)}</p>`:''}</div><div class="ct-now ${st.cls||''}">${st.n?esc(TRACK_STEPS[st.n-1][0]):'Not bidding'}<small>${esc(st.note||(st.n?TRACK_STEPS[st.n-1][1]:''))}</small></div></header>
    ${steps}
    <div class="ct-facts"><div><span>Bid due</span><b>${b.due_date?fmtDate(b.due_date):'Not set'}</b>${b.due_time?`<small>${esc(b.due_time)}</small>`:''}</div>
      <div><span>${b.sent?'Proposal sent':'Proposal expected by'}</span><b>${b.sent?(b.sent_date?fmtDate(b.sent_date):'Sent'):b.proposal_eta?fmtDate(b.proposal_eta):'To be confirmed'}</b></div>
      <div><span>Addenda acknowledged</span>${ad.length?`<div class="ct-ad">${ad.map(a=>`<i class="${a.acknowledged?'ok':''}" title="${a.acknowledged?'Acknowledged':'Received, not yet acknowledged'}${a.date?' · issued '+fmtShort(a.date):''}">${a.acknowledged?'✓ ':''}#${esc(a.number)}</i>`).join('')}</div>`:'<b>None so far</b>'}</div>
      <div><span>Your estimator</span>${e&&e.name?`<b>${esc(e.name)}</b>${e.title?`<small>${esc(e.title)}</small>`:''}<small>${e.phone?`<a href="tel:${esc(e.phone)}">${esc(e.phone)}</a>`:''}${e.phone&&e.email?' · ':''}${e.email?`<a href="mailto:${esc(e.email)}">${esc(e.email)}</a>`:''}</small>`:'<b>To be assigned</b>'}</div></div></article>`}
async function trackPage(tk){const main=$('#main'),top=$('#topwrap');if(top)top.hidden=true;document.title=`Bid tracker — ${S.settings?.general?.companyName||CFG.companyName||APP_NAME}`;const co=CFG.companyName||APP_NAME;const logo=BRAND.loginLogo||'';
  const shell=inner=>`<div class="ct"><div class="ct-head">${logo?`<img src="${esc(logo)}" alt="${esc(co)}">`:`<b class="ct-co">${esc(co)}</b>`}<span>Bid tracker</span></div>${inner}<p class="ct-foot">${esc(co)} · This page is private to your company. It updates on its own as our estimating team moves each bid along.</p></div>`;
  const draw=async first=>{let d=null,err=null;try{const r=await sb.rpc('client_tracker',{p_token:tk});if(r.error)err=r.error;else d=r.data}catch(e){err=e}
    if(err){if(first)main.innerHTML=shell(`<div class="ct-msg"><h1>We couldn’t load the tracker</h1><p>Please try again in a few minutes.</p></div>`);return}
    if(!d){main.innerHTML=shell(`<div class="ct-msg"><h1>This link isn’t active</h1><p>It may have been replaced. Please ask your contact at ${esc(co)} for a new one.</p></div>`);return}
    data=d;if(!$('#ct-list'))main.innerHTML=shell(`<div class="ct-title"><h1>${esc(d.client||'Your projects')}</h1><p id="ct-count"></p></div>
      <div class="ct-bar"><input class="field" id="ct-q" type="search" placeholder="Search projects or locations" aria-label="Search"><select class="field" id="ct-stage" aria-label="Stage"><option value="">All stages</option>${TRACK_STEPS.slice(0,4).map(([l],i)=>`<option value="${i+1}">${l}</option>`).join('')}<option value="hold">On hold</option></select>
        <select class="field" id="ct-sort" aria-label="Sort"><option value="due">Bid due date</option><option value="name">Project name</option><option value="stage">Stage</option><option value="new">Newest first</option></select></div><div id="ct-list"></div>`);
    list()};
  let data=null;
  const list=()=>{if(!data||!$('#ct-list'))return;const q=($('#ct-q').value||'').trim().toLowerCase(),sg=$('#ct-stage').value,so=$('#ct-sort').value;
    const all=data.bids.filter(b=>!['Awarded','Not Awarded','No Bid'].includes(b.status));
    let L=all.filter(b=>(!q||(b.name+' '+(b.location||'')).toLowerCase().includes(q))&&(!sg||(sg==='hold'?b.status==='On Hold':b.status!=='On Hold'&&String(trackStage(b).n)===sg)));
    const key={due:b=>b.due_date||'9999',name:b=>String(b.name).toLowerCase(),stage:b=>String(9-trackStage(b).n),new:b=>String(b.received||'')}[so];L=L.slice().sort((a,c)=>key(a).localeCompare(key(c)));if(so==='new')L.reverse();
    $('#ct-count').textContent=`${all.length} bid${all.length===1?'':'s'} in progress${L.length!==all.length?` · showing ${L.length}`:''} · updated ${new Date(data.as_of||Date.now()).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`;
    $('#ct-list').innerHTML=L.map(trackCard).join('')||`<div class="ct-msg"><p>${all.length?'Nothing matches that search.':'No bids in progress right now.'}</p></div>`};
  document.addEventListener('input',e=>{if(e.target.id==='ct-q')list()});document.addEventListener('change',e=>{if(e.target.id==='ct-stage'||e.target.id==='ct-sort')list()});
  main.innerHTML=shell(`<div class="ct-msg">${dozerLoader('Loading')}</div>`);await draw(true);setInterval(()=>{if(!document.hidden)draw(false)},60000)}
/* ---- staff side ---- */
function trackEmail(c,b,url){const who=String((b&&(b.client_contacts||{})[c.id])||'').split(/[,(]/)[0].trim();const co=S.settings.general?.companyName||CFG.companyName||'';const me=myEst();
  return {subject:`${co?co+' — ':''}bid tracker${b?' for '+b.name:''}`,
    body:`${who?'Hi '+who.split(' ')[0]:'Hello'},\n\n${b?`Thank you for the invitation to bid ${b.name}. `:''}The link below is for tracking purposes. It shows where our bid stands on every project you’ve sent us: the stage it’s in, the bid due date, when to expect our proposal, the addenda we’ve acknowledged and who to call with questions.\n\n${url}\n\nNo login is needed, and the same link keeps working for future projects. It’s private to ${c.company||'your company'}, so please keep it within your team.\n\nThank you,\n${myName()}${me&&me.phone?'\n'+me.phone:''}${co?'\n'+co:''}`}}
async function trackOpen(clientIds,bidId){const ids=(clientIds||[]).filter(id=>byId(S.clients,id));if(!ids.length)return;M={kind:'track',ids,bidId:bidId||null,cur:ids[0],links:{},fromNew:!!bidId&&M===null};showModal();trackLoad(ids[0])}
async function trackLoad(id,fresh){const x=M;if(!x||x.kind!=='track')return;try{const tk=await run(sb.rpc('client_track_link',{p_client:id,p_new:!!fresh}));x.links[id]=tk;x.err=null}catch(e){x.err=/client_track_link|does not exist|schema cache|PGRST202/i.test(errMsg(e))?TRACK_SQL:errMsg(e)}if(M===x)renderModal()}
function trackModal(){const x=M;const c=byId(S.clients,x.cur)||{};const b=x.bidId?byId(S.bids,x.bidId):null;const tk=x.links[x.cur];const url=tk?trackUrl(tk):'';const em=tk?trackEmail(c,b,url):null;
  const n=S.bids.filter(q=>(q.client_ids||[]).includes(c.id)&&!q.archived_at&&!DECIDED.includes(q.status)).length;
  return mhead('Client tracker link',b?`${b.name} — send the GC their tracking link`:c.company||'')+`<div class="mbody">
    ${x.ids.length>1?`<div class="seg" style="margin-bottom:12px">${x.ids.map(id=>`<button class="${id===x.cur?'on':''}" data-act="trk-pick" data-id="${id}">${esc(byId(S.clients,id)?.company||'')}</button>`).join('')}</div>`:''}
    ${x.err?`<div class="notice">${esc(x.err)}</div>`:!tk?'<p class="dim">Getting the link…</p>':`
    <p class="small" style="margin:0 0 10px"><b>${esc(c.company||'This client')}</b> has one private link. It shows all ${n} of their bids in progress and any new ones you add later, so you only need to send it once.</p>
    <fieldset><legend>Link</legend><div class="pt-row"><input class="field" id="trk-url" readonly value="${esc(url)}" onfocus="this.select()"><button class="btn primary" data-act="trk-copy" data-v="url">Copy link</button><a class="btn" href="${esc(url)}" target="_blank" rel="noopener">Preview</a></div></fieldset>
    <fieldset><legend>Email to send them</legend><label class="f">Subject<input class="field" id="trk-subj" data-trk="subject" value="${esc(x.subject??em.subject)}"></label><label class="f">Message<textarea class="field" id="trk-body" data-trk="body" rows="11">${esc(x.body??em.body)}</textarea></label>
      <div class="adders"><button class="btn primary" data-act="trk-copy" data-v="email">Copy email</button><button class="btn" data-act="trk-mail">Open in my email</button></div>
      <p class="hint">Paste it into Outlook or Gmail and send it yourself. The client sees stages, dates, acknowledged addenda and the lead estimator’s contact — never prices, other GCs or your notes.</p></fieldset>
    ${isAdmin()?`<button class="btn sm ghost${x.arm2?' danger':''}" data-act="trk-new">${x.arm2?'Click again — the old link stops working':'Replace this link (turns the old one off)'}</button>`:''}`}</div>
  <div class="mfoot"><div></div><div class="r"><button class="btn" data-act="close">${x.bidId?'Done':'Close'}</button></div></div>`}
function trackRow(b){if(!b||b._new||!can('bids','edit'))return '';const ids=(b.client_ids||[]).filter(id=>byId(S.clients,id));if(!ids.length)return '';
  return `<div class="trk-row small"><span class="dim">Client tracker:</span> ${ids.map(id=>`<button class="linkbtn" data-act="trk-open" data-id="${id}" data-bid="${b.id}">${esc(byId(S.clients,id).company)}</button>`).join(' · ')}</div>`}
FOCUS_ATTRS.push('data-trk');
document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t)return;const a=t.dataset.act;if(!a.startsWith('trk-'))return;const x=M&&M.kind==='track'?M:null;
  const copy=(txt,msg)=>(navigator.clipboard?navigator.clipboard.writeText(txt):Promise.reject()).then(()=>toast(msg)).catch(()=>toast('Couldn’t copy — select the text and copy it by hand.'));
  const cur=()=>{const c=byId(S.clients,x.cur)||{};const b=x.bidId?byId(S.bids,x.bidId):null;const em=trackEmail(c,b,trackUrl(x.links[x.cur]));return {subject:x.subject??em.subject,body:x.body??em.body,c,b}};
  switch(a){
    case 'trk-open':{const bid=t.dataset.bid||null;const id=t.dataset.id;closeModal();M={kind:'track',ids:[id],bidId:bid,cur:id,links:{}};showModal();trackLoad(id);break}
    case 'trk-pick':if(x){x.cur=t.dataset.id;x.subject=x.body=undefined;x.arm2=false;renderModal();if(!x.links[x.cur])trackLoad(x.cur)}break;
    case 'trk-copy':if(x&&x.links[x.cur]){if(t.dataset.v==='url')copy(trackUrl(x.links[x.cur]),'Link copied');else{const m=cur();copy(`Subject: ${m.subject}\n\n${m.body}`,'Email copied')}}break;
    case 'trk-mail':if(x&&x.links[x.cur]){const m=cur();const to=(/[^\s<>(),;]+@[^\s<>(),;]+/.exec(String((m.b&&(m.b.client_contacts||{})[m.c.id])||'')+' '+String(m.c.email||''))||[''])[0];location.href=`mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(m.subject)}&body=${encodeURIComponent(m.body)}`}break;
    case 'trk-new':if(x&&isAdmin()){if(!x.arm2){x.arm2=true;renderModal();break}x.arm2=false;x.subject=x.body=undefined;delete x.links[x.cur];renderModal();trackLoad(x.cur,true).then(()=>toast('New link made. The old one no longer works.'))}break;
  }});
document.addEventListener('input',e=>{const t=e.target;if(M&&M.kind==='track'&&t.dataset.trk)M[t.dataset.trk]=t.value});


/* ---- pipeline stage bar on the bid: where it is, and click to move it ---- */
function stageBar(b,work){const steps=[...PRE_SUBMIT,'Submitted'];const cur=steps.indexOf(b.status);const dec=DECIDED.includes(b.status);const n=dec?steps.length:cur;
  return `<div class="stg${b.status==='On Hold'?' hold':''}" role="group" aria-label="Pipeline stage">${steps.map((s,i)=>`<button type="button" class="${i<n?'past':i===n?'now':''}" data-act="bid-stage" data-v="${s}" title="${esc(BID_ABOUT[s]||'')}"${work?'':' disabled'}><i>${i<n?'✓':i+1}</i><span>${s==='Submitted'?'Proposal sent':s}</span></button>`).join('')}
    <span class="stg-end">${dec?pill(b.status,BID_CLS[b.status]):b.status==='On Hold'?pill('On Hold','warn'):''}</span></div>`}
document.addEventListener('click',e=>{const t=e.target.closest('[data-act=bid-stage]');if(!t||!M||M.kind!=='bid'||t.disabled)return;M.draft.status=t.dataset.v;renderModal()});

/* =====================================================================
   GC follow-up after the proposal goes out.
   A week (or whatever the bid says) after sending, the bid shows up under
   "Follow-ups due" for its estimator and for managers. The app drafts the
   email, logs the nudge, tracks the Teams/Zoom meeting and what was learned.
   Plan lives on the bid (bids.follow_plan); nudges go in the follow-up log.
   ===================================================================== */
const fuTime=t=>{const m=/^(\d{1,2}):(\d{2})/.exec(String(t||''));if(!m)return String(t||'');const h=+m[1];return `${h%12||12}:${m[2]} ${h<12?'AM':'PM'}`};
const FU_SQL='GC follow-ups need a one-time database update (update-30-follow-ups.sql).';
const FU_STANDING=['No feedback yet','We’re low','We’re competitive','We’re high','Waiting on the owner','Budget / redesign','Project delayed'];
const fuDefaults=()=>{const g=S.settings.general||{};return {days:num(g.fuDays)||7,rounds:num(g.fuRounds)||3}};
const fuPlan=b=>{const p=b.follow_plan&&typeof b.follow_plan==='object'?b.follow_plan:{};const D=fuDefaults();return {days:num(p.days)>0?num(p.days):D.days,rounds:p.rounds!=null&&p.rounds!==''&&num(p.rounds)>=0?num(p.rounds):D.rounds,off:!!p.off,snooze:p.snooze||'',meeting:p.meeting&&typeof p.meeting==='object'?p.meeting:null,decision:p.decision||'',custom:{days:p.days,rounds:p.rounds}}};
const fuSentDate=b=>b.submitted_date||(b.client_ids||[]).map(id=>propOf(b,id).sent_date).filter(Boolean).sort()[0]||'';
const addDays=(iso,n)=>{const d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+Math.round(n));return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
// where a submitted bid stands on follow-up: {kind:'nudge'|'meeting'|'outcome'|'decision'|null, due, n, …}
function fuState(b){const P=fuPlan(b);const sent=fuSentDate(b);const today=todayStr();const nudges=(b.follow_ups||[]).filter(f=>f.kind==='nudge'&&f.date&&(!sent||f.date>=sent)).sort((a,c)=>String(a.date).localeCompare(String(c.date)));
  const o={P,sent,n:nudges.length,last:nudges.length?nudges[nudges.length-1].date:'',kind:null,due:'',label:''};
  if(b.status!=='Submitted'||b.archived_at||!sent||P.off)return o;
  const m=P.meeting;
  if(m&&m.date&&!m.held){if(m.date>=today){o.kind='meeting';o.due=m.date;o.label=`Meeting ${fmtShort(m.date)}${m.time?' at '+fuTime(m.time):''}`;o.wait=true}else{o.kind='outcome';o.due=m.date;o.label='Record what you learned in the meeting'}return o}
  if(P.decision){o.kind='decision';o.due=P.decision;o.label=`Decision expected ${fmtShort(P.decision)}`;o.wait=P.decision>today;if(!o.wait)o.label='Decision was expected — check in';return o}
  if(o.n>=P.rounds){o.done=true;o.label=P.rounds?`All ${P.rounds} follow-up${P.rounds===1?'':'s'} sent`:'No follow-ups planned';return o}
  o.kind='nudge';o.due=addDays(o.last||sent,P.days);if(P.snooze&&P.snooze>o.due)o.due=P.snooze;o.wait=o.due>today;o.label=`Follow-up ${o.n+1} of ${P.rounds}`;return o}
const fuIsDue=b=>{const s=fuState(b);return !!s.kind&&!s.wait};
function fuList(){const mine=!bidsAll();return S.bids.filter(b=>live(b)&&b.status==='Submitted'&&(mine?assigned(b):true)).map(b=>({b,s:fuState(b)})).filter(x=>x.s.kind).sort((a,c)=>String(a.s.due).localeCompare(String(c.s.due)))}
function fuPanel(){if(!can('bids'))return '';const L=fuList();const due=L.filter(x=>!x.s.wait),soon=L.filter(x=>x.s.wait&&daysUntil(x.s.due)<=7);if(!due.length&&!soon.length)return '';
  const worst=due.length?-daysUntil(due[0].s.due):0;
  return `<button class="panel pad fu-block${due.length?'':' quiet'}" data-act="fu-list"><span class="fu-n">${due.length||soon.length}</span><span class="fu-t"><b>${due.length?`bid${due.length===1?'':'s'} need${due.length===1?'s':''} a GC follow-up`:`GC follow-up${soon.length===1?'':'s'} coming up this week`}</b><small>${due.length?`${soon.length?soon.length+' more coming up this week · ':''}oldest is ${worst} day${worst===1?'':'s'} overdue`:'Nothing due today'}</small></span><span class="fu-go">Show them ›</span></button>`}
function fuListModal(){const x=M;const L=fuList();const q=(x.q||'').trim().toLowerCase();const f=x.f||'due';
  const due=L.filter(o=>!o.s.wait),soon=L.filter(o=>o.s.wait);let R=(f==='due'?due:f==='soon'?soon:L).filter(o=>!q||[o.b.name,o.b.location,(o.b.client_ids||[]).map(clientName).join(' '),estName(o.b.lead_estimator_id)].join(' ').toLowerCase().includes(q));
  if(x.sort==='name')R=R.slice().sort((a,c)=>String(a.b.name).localeCompare(String(c.b.name)));else if(x.sort==='gc')R=R.slice().sort((a,c)=>String(clientName((a.b.client_ids||[])[0])||'~').localeCompare(String(clientName((c.b.client_ids||[])[0])||'~')));
  const old=due.filter(o=>canWork(o.b)&&-daysUntil(o.s.due)>30);
  const row=o=>{const d=daysUntil(o.s.due);const gc=(o.b.client_ids||[]).map(clientName).filter(Boolean).slice(0,2).join(', ');
    return `<tr><td class="proj"><button class="linkbtn" data-act="fu-open" data-id="${o.b.id}">${esc(o.b.name)}</button>${o.b.location?`<div class="dim small">${esc(o.b.location)}</div>`:''}</td><td class="small">${esc(gc||'—')}</td><td class="small">${o.b.lead_estimator_id?esc(estName(o.b.lead_estimator_id)):'<span class="dim">—</span>'}</td><td class="small">${o.s.sent?fmtShort(o.s.sent):''}</td>
      <td class="small">${esc(o.s.label)}</td><td class="small ${o.s.wait?'dim':'warn-t'}" style="white-space:nowrap">${o.s.wait?(d===0?'today':'in '+d+' day'+(d===1?'':'s')):d===0?'due today':-d+' day'+(d===-1?'':'s')+' overdue'}</td>
      <td class="r nowrap">${canWork(o.b)?`<button class="btn sm primary" data-act="fu-open" data-id="${o.b.id}">${o.s.kind==='outcome'?'Record meeting':'Follow up…'}</button><button class="btn sm ghost" data-act="fu-off" data-id="${o.b.id}" title="Stop reminders for this bid">Pause</button>`:''}</td></tr>`};
  return mhead('GC follow-ups',`${due.length} due · ${soon.length} coming up`)+`<div class="mbody">
    <div class="bar" style="margin-top:0"><input class="field search" id="ful-q" data-ful="q" placeholder="Search project, GC or estimator" value="${esc(x.q||'')}"><div class="seg">${[['due',`Due (${due.length})`],['soon',`Coming up (${soon.length})`],['all','All']].map(([k,l])=>`<button class="${f===k?'on':''}" data-act="fu-f" data-v="${k}">${l}</button>`).join('')}</div>
      <select class="field" data-fulsort aria-label="Sort"><option value="">Most overdue first</option><option value="name"${x.sort==='name'?' selected':''}>Project name</option><option value="gc"${x.sort==='gc'?' selected':''}>GC</option></select></div>
    ${old.length&&f!=='soon'?`<div class="notice fu-old"><span><b>${old.length}</b> of these went out more than a month ago. If they’re stale, pause them so the list shows what’s current. You can turn any bid back on from its follow-up window.</span> <button class="btn sm${x.armOld?' danger':''}" data-act="fu-offold">${x.armOld?`Click again to pause ${old.length}`:`Pause those ${old.length}`}</button></div>`:''}
    <div class="panel scroll"><table><thead><tr><th>Project</th><th>GC</th><th>Estimator</th><th>Sent</th><th>Next step</th><th>When</th><th></th></tr></thead><tbody>${R.map(row).join('')||'<tr><td colspan="7"><div class="empty">Nothing here.</div></td></tr>'}</tbody></table></div></div>
  <div class="mfoot"><div></div><div class="r"><button class="btn" data-act="close">Close</button></div></div>`}
function fuEmail(b,cid,type,st){const c=byId(S.clients,cid)||{};const who=String((b.client_contacts||{})[cid]||'').split(/[,(]/)[0].trim().split(' ')[0];const co=S.settings.general?.companyName||CFG.companyName||'';const me=myEst();const hi=who?'Hi '+who:'Hello';
  const sign=`\n\nThank you,\n${myName()}${me&&me.phone?'\n'+me.phone:''}${co?'\n'+co:''}`;const sent=fuSentDate(b);const when=sent?` on ${fmtDate(sent)}`:'';const m=st.P.meeting||{};
  if(type==='meeting')return {subject:`${b.name} — time to review our proposal?`,body:`${hi},\n\nI’d like to set up a short Teams or Zoom call to walk through our proposal for ${b.name}. Twenty minutes is plenty. It gives us a chance to confirm scope, answer any questions and make sure nothing is missing or double-counted.\n\nWould any of these work?\n  • \n  • \n  • \n\nIf another time is better, send it over and I’ll make it work.${sign}`};
  if(type==='confirm')return {subject:`${b.name} — proposal review ${m.date?fmtDate(m.date):''}${m.time?' at '+fuTime(m.time):''}`,body:`${hi},\n\nConfirming our call to review the ${b.name} proposal${m.date?' on '+fmtDate(m.date):''}${m.time?' at '+fuTime(m.time):''}.${m.link?`\n\nJoin here: ${m.link}`:''}\n\nIf there’s anything you’d like us to have ready, let me know.${sign}`};
  const n=st.n+1;
  if(n<=1)return {subject:`${b.name} — following up on our proposal`,body:`${hi},\n\nI wanted to follow up on the proposal we sent for ${b.name}${when}. Has your team had a chance to review it?\n\nIf you have questions on scope, quantities or anything we excluded, I’m glad to walk through it. I can also set up a quick Teams or Zoom call if that’s easier.${sign}`};
  if(n===2)return {subject:`${b.name} — checking in`,body:`${hi},\n\nChecking back in on ${b.name}. Is there an update on where the project stands or when you expect a decision?\n\nIf our number needs another look, or the scope has changed since we priced it, send over what you have and we’ll turn it around quickly.${sign}`};
  return {subject:`${b.name} — still interested`,body:`${hi},\n\nI know these decisions take time, so I’ll keep this short. We’re still very interested in ${b.name} and have the crews to start when you need us.\n\nCould you let me know where things stand, even if nothing has been decided yet? It helps us hold room in our schedule.${sign}`}}
function fuOpen(bidId){const b=byId(S.bids,bidId);if(!b)return;const st=fuState(b);const P=st.P;M={kind:'fu',bidId,cid:(b.client_ids||[])[0]||'',type:st.kind==='nudge'||!st.kind?'nudge':'meeting',days:P.custom.days??'',rounds:P.custom.rounds??'',mt:{date:P.meeting?.date||'',time:P.meeting?.time||'',link:P.meeting?.link||''},out:{standing:FU_STANDING[0],decision:'',comp:'',notes:'',prob:b.probability??50}};showModal()}
function fuModal(){const x=M;const b=byId(S.bids,x.bidId);if(!b)return mhead('Follow-up','')+'<div class="mbody"></div>';const st=fuState(b);const P=st.P;const work=canWork(b);const dis=work?'':' disabled';const D=fuDefaults();
  const em=x.cid?fuEmail(b,x.cid,x.type,st):null;const log=(b.follow_ups||[]).filter(f=>f.date||f.note).slice().sort((a,c)=>String(c.date).localeCompare(String(a.date))).slice(0,6);const m=P.meeting;
  const steps=[['Proposal sent',st.sent?fmtShort(st.sent):'—',1],[`Follow-ups`,`${st.n} of ${P.rounds}`,st.n>0?(st.n>=P.rounds?1:.5):0],['Meeting',m&&m.date?(m.held?'Held '+fmtShort(m.date):fmtShort(m.date)):'Not set',m&&m.held?1:m&&m.date?.5:0],['Decision',P.decision?'Expected '+fmtShort(P.decision):'Waiting',0]];
  return mhead('GC follow-up',b.name)+`<div class="mbody">
    ${b.follow_plan===undefined?`<div class="notice">${FU_SQL}</div>`:''}
    <div class="fu-steps">${steps.map(([l,v,p])=>`<div class="${p>=1?'done':p>0?'cur':''}"><span>${l}</span><b>${esc(v)}</b></div>`).join('')}</div>
    <p class="small ${st.kind&&!st.wait?'warn-t':'dim'}" style="margin:8px 0 14px">${b.status!=='Submitted'?`This bid is ${esc(b.status)}, so follow-ups are off.`:!st.sent?'No sent date on this bid yet.':P.off?'Follow-ups are paused for this bid.':esc(st.label)+(st.due&&st.kind?` · ${st.wait?'due':'was due'} ${fmtShort(st.due)}`:'')}</p>
    ${st.kind==='outcome'?`<fieldset class="fu-hot"><legend>What did you learn in the meeting?</legend><div class="fg">
      <label class="f s2">Where we stand<select class="field" data-fuo="standing"${dis}>${FU_STANDING.map(s=>`<option${x.out.standing===s?' selected':''}>${s}</option>`).join('')}</select></label>
      <label class="f">Decision expected<input type="date" class="field" id="fuo-dec" data-fuo="decision" value="${esc(x.out.decision)}"${dis}></label><label class="f">Win probability %<input class="field num" id="fuo-prob" data-fuo="prob" inputmode="numeric" value="${esc(x.out.prob)}"${dis}></label>
      <label class="f s2">Who else is in it<input class="field" id="fuo-comp" data-fuo="comp" value="${esc(x.out.comp)}" placeholder="Other bidders, if they said"${dis}></label><label class="f s2">Notes<input class="field" id="fuo-notes" data-fuo="notes" value="${esc(x.out.notes)}" placeholder="Scope questions, what they want changed…"${dis}></label></div>
      <div class="adders"><button class="btn primary" data-act="fu-held"${dis}>Save meeting notes</button><button class="btn" data-act="fu-nomeet"${dis}>It didn’t happen</button></div></fieldset>`:''}
    <fieldset><legend>Email the GC</legend>
      <div class="fg"><label class="f s2">To<select class="field" data-fu="cid"${dis}>${(b.client_ids||[]).map(id=>`<option value="${id}"${x.cid===id?' selected':''}>${esc(clientName(id))}${(b.client_contacts||{})[id]?' — '+esc(b.client_contacts[id]):''}</option>`).join('')||'<option value="">No GC on this bid</option>'}</select></label>
      <label class="f s2">Kind<select class="field" data-fu="type"${dis}><option value="nudge"${x.type==='nudge'?' selected':''}>Follow-up ${Math.min(st.n+1,Math.max(P.rounds,1))}</option><option value="meeting"${x.type==='meeting'?' selected':''}>Ask for a Teams / Zoom review</option>${m&&m.date&&!m.held?`<option value="confirm"${x.type==='confirm'?' selected':''}>Confirm the meeting</option>`:''}</select></label></div>
      ${em?`<label class="f">Subject<input class="field" id="fu-subj" data-fu="subject" value="${esc(x.subject??em.subject)}"${dis}></label><label class="f">Message<textarea class="field" id="fu-body" data-fu="body" rows="9"${dis}>${esc(x.body??em.body)}</textarea></label>
      <div class="adders"><button class="btn" data-act="fu-copy">Copy email</button><button class="btn" data-act="fu-mail">Open in my email</button>${work?`<button class="btn primary" data-act="fu-sent">I sent it — log it</button>`:''}</div><p class="hint">Send it from your own email, then click <b>I sent it</b>. That logs the follow-up and starts the clock for the next one.</p>`:''}</fieldset>
    <fieldset><legend>Teams / Zoom meeting</legend><div class="fg"><label class="f">Date<input type="date" class="field" id="fum-date" data-fum="date" value="${esc(x.mt.date)}"${dis}></label><label class="f">Time<input type="time" class="field" id="fum-time" data-fum="time" value="${esc(x.mt.time)}"${dis}></label><label class="f s2">Meeting link<input class="field" id="fum-link" data-fum="link" value="${esc(x.mt.link)}" placeholder="Paste the Teams or Zoom link"${dis}></label></div>
      ${work?`<div class="adders"><button class="btn" data-act="fu-meet">${m&&m.date&&!m.held?'Update meeting':'Meeting scheduled'}</button>${m&&m.date&&!m.held?'<button class="btn ghost" data-act="fu-nomeet">Cancel meeting</button>':''}</div>`:''}
      ${m&&m.held&&m.outcome?`<p class="small" style="margin:8px 0 0"><b>Last meeting ${fmtShort(m.date)}:</b> ${esc(m.outcome.standing||'')}${m.outcome.comp?' · also bidding: '+esc(m.outcome.comp):''}${m.outcome.notes?' · '+esc(m.outcome.notes):''}</p>`:''}</fieldset>
    <fieldset><legend>This bid’s follow-up plan</legend><div class="fg"><label class="f">Days between follow-ups<input class="field num" id="fu-days" data-fu="days" inputmode="numeric" value="${esc(x.days)}" placeholder="${D.days}"${dis}></label><label class="f">How many follow-ups<input class="field num" id="fu-rounds" data-fu="rounds" inputmode="numeric" value="${esc(x.rounds)}" placeholder="${D.rounds}"${dis}></label>
      <div class="f s2" style="justify-content:flex-end">${work?`<div class="adders" style="margin:0"><button class="btn sm" data-act="fu-plan">Save plan</button><button class="btn sm" data-act="fu-snooze" title="Push the next reminder back a week">Remind me in a week</button><button class="btn sm ghost" data-act="fu-pause">${P.off?'Turn follow-ups back on':'Pause follow-ups'}</button></div>`:''}</div></div>
      <p class="hint">Blank uses the company default (${D.days} days, ${D.rounds} follow-ups).${isAdmin()?' <button class="linkbtn" data-act="fu-default">Change the default</button>':''}</p></fieldset>
    ${log.length?`<fieldset><legend>Follow-up log</legend>${log.map(f=>`<div class="small" style="padding:3px 0"><b>${f.date?fmtShort(f.date):''}</b> ${esc(f.note||'')}</div>`).join('')}</fieldset>`:''}</div>
  <div class="mfoot"><div>${x.back?'<button class="btn" data-act="fu-back">‹ Back to the list</button>':''}<button class="btn" data-act="fu-bid">Open the bid</button></div><div class="r"><button class="btn" data-act="close">Close</button></div></div>`}
async function fuWrite(b,patch,logLine,extra){const plan={...(b.follow_plan&&typeof b.follow_plan==='object'?b.follow_plan:{}),...(patch||{})};Object.keys(plan).forEach(k=>{if(plan[k]===undefined)delete plan[k]});
  const up={follow_plan:plan,...(extra||{})};if(logLine)up.follow_ups=[...(b.follow_ups||[]),{date:todayStr(),...logLine}];
  try{await run(sb.from('bids').update(up).eq('id',b.id));await loadTable('bids');if(M&&M.kind==='fu'){M.subject=M.body=undefined;renderModal()}render();return true}
  catch(e){toast(/follow_plan|column|schema cache/i.test(errMsg(e))?FU_SQL:errMsg(e));return false}}
function fuRow(b){if(!b||b._new||b.status!=='Submitted')return '';const s=fuState(b);return `<div class="trk-row small"><span class="dim">GC follow-up:</span> ${esc(s.label||'not started')}${s.due&&s.kind?` · ${s.wait?'due':'was due'} ${fmtShort(s.due)}`:''} <button class="linkbtn" data-act="fu-open" data-id="${b.id}">${canWork(b)?'Follow up…':'View'}</button></div>`}
FOCUS_ATTRS.push('data-fu','data-fum','data-fuo');
document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t||t.tagName==='SELECT')return;const a=t.dataset.act;if(!a.startsWith('fu-'))return;
  if(a==='fu-list'){M={kind:'fulist',q:'',f:fuList().some(o=>!o.s.wait)?'due':'soon',sort:''};showModal();return}
  if(a==='fu-open'){const back=M&&M.kind==='fulist'?{...M}:null;closeModal();fuOpen(t.dataset.id);if(M)M.back=back;return}
  if(a==='fu-f'&&M&&M.kind==='fulist'){M.f=t.dataset.v;renderModal();return}
  if(a==='fu-back'&&M&&M.back){M={...M.back};M.armOld=false;renderModal();return}
  if((a==='fu-off'||a==='fu-offold')&&M&&M.kind==='fulist'){let ids;if(a==='fu-off')ids=[t.dataset.id];else{if(!M.armOld){M.armOld=true;renderModal();return}M.armOld=false;ids=fuList().filter(o=>!o.s.wait&&canWork(o.b)&&-daysUntil(o.s.due)>30).map(o=>o.b.id)}
    Promise.all(ids.map(id=>{const b=byId(S.bids,id);return b&&canWork(b)?sb.from('bids').update({follow_plan:{...(b.follow_plan&&typeof b.follow_plan==='object'?b.follow_plan:{}),off:true}}).eq('id',id):null})).then(rs=>{const er=rs.find(r=>r&&r.error);return loadTable('bids').then(()=>{if(M&&M.kind==='fulist')renderModal();render();toast(er?(/follow_plan|column|schema cache/i.test(errMsg(er.error))?FU_SQL:errMsg(er.error)):`Paused follow-ups on ${ids.length} bid${ids.length===1?'':'s'}`)})});return}
  const x=M&&M.kind==='fu'?M:null;if(!x)return;const b=byId(S.bids,x.bidId);if(!b)return;const st=fuState(b);const em=x.cid?fuEmail(b,x.cid,x.type,st):{subject:'',body:''};const subj=x.subject??em.subject,body=x.body??em.body;const gc=clientName(x.cid)||'the GC';
  const copy=(txt,msg)=>(navigator.clipboard?navigator.clipboard.writeText(txt):Promise.reject()).then(()=>toast(msg)).catch(()=>toast('Couldn’t copy — select the text and copy it by hand.'));
  if(a==='fu-copy'){copy(`Subject: ${subj}\n\n${body}`,'Email copied');return}
  if(a==='fu-mail'){const c=byId(S.clients,x.cid)||{};const to=(/[^\s<>(),;]+@[^\s<>(),;]+/.exec(String((b.client_contacts||{})[x.cid]||'')+' '+String(c.email||''))||[''])[0];location.href=`mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(subj)}&body=${encodeURIComponent(body)}`;return}
  if(a==='fu-bid'){closeModal();openBid(b.id);return}
  if(a==='fu-default'&&isAdmin()){const D=fuDefaults();const d=prompt('Days between follow-ups (company default)',D.days);if(d===null)return;const r=prompt('How many follow-ups (company default)',D.rounds);if(r===null)return;
    const g={...(S.settings.general||{}),fuDays:Math.max(1,Math.round(num(d)||7)),fuRounds:Math.max(0,Math.round(num(r)??3))};run(sb.from('settings').upsert({key:'general',value:g})).then(()=>loadTable('settings')).then(()=>{renderModal();render();toast('Default saved')}).catch(er=>toast(errMsg(er)));return}
  if(!canWork(b))return;
  switch(a){
    case 'fu-sent':{const kind=x.type==='nudge'?'nudge':'note';const note=x.type==='nudge'?`Follow-up ${st.n+1} emailed to ${gc}`:x.type==='meeting'?`Asked ${gc} for a Teams/Zoom proposal review`:`Confirmed the meeting with ${gc}`;
      fuWrite(b,x.type==='nudge'?{snooze:undefined}:{},{note,kind:x.type==='meeting'?'nudge':kind,client_id:x.cid,by:myName()}).then(ok=>{if(ok)toast('Logged')});break}
    case 'fu-meet':{if(!x.mt.date){toast('Pick the meeting date.');break}fuWrite(b,{meeting:{date:x.mt.date,time:x.mt.time||'',link:x.mt.link||'',held:false},decision:undefined},{note:`Meeting set with ${gc} for ${fmtShort(x.mt.date)}${x.mt.time?' at '+x.mt.time:''}`,kind:'meeting',client_id:x.cid,by:myName()}).then(ok=>{if(ok){M.type='confirm';renderModal();toast('Meeting saved')}});break}
    case 'fu-nomeet':{x.mt={date:'',time:'',link:''};fuWrite(b,{meeting:undefined},{note:'Meeting cancelled / didn’t happen',kind:'note',by:myName()}).then(ok=>{if(ok)toast('Meeting cleared')});break}
    case 'fu-held':{const o=x.out;const mt={...(st.P.meeting||{}),held:true,outcome:{standing:o.standing,comp:String(o.comp||'').trim(),notes:String(o.notes||'').trim()}};const pr=num(o.prob);
      fuWrite(b,{meeting:mt,decision:o.decision||undefined},{note:`Meeting held: ${o.standing}${o.comp?' · also bidding: '+String(o.comp).trim():''}${o.decision?' · decision expected '+fmtShort(o.decision):''}${o.notes?' · '+String(o.notes).trim():''}`,kind:'meeting',client_id:x.cid,by:myName()},pr!=null&&pr>=0&&pr<=100?{probability:Math.round(pr)}:{}).then(ok=>{if(ok)toast('Meeting notes saved')});break}
    case 'fu-plan':{const d=String(x.days).trim(),r=String(x.rounds).trim();fuWrite(b,{days:d===''?undefined:Math.max(1,Math.round(num(d)||7)),rounds:r===''?undefined:Math.max(0,Math.round(num(r)||0))}).then(ok=>{if(ok)toast('Plan saved')});break}
    case 'fu-snooze':fuWrite(b,{snooze:addDays(todayStr(),7)}).then(ok=>{if(ok)toast('Next reminder pushed back a week')});break;
    case 'fu-pause':fuWrite(b,{off:!st.P.off}).then(ok=>{if(ok)toast(st.P.off?'Follow-ups back on':'Follow-ups paused for this bid')});break;
  }});
document.addEventListener('input',e=>{const t=e.target;if(!M||M.kind!=='fu')return;if(t.dataset.fu&&t.tagName!=='SELECT')M[t.dataset.fu]=t.value;else if(t.dataset.fum)M.mt[t.dataset.fum]=t.value;else if(t.dataset.fuo&&t.tagName!=='SELECT')M.out[t.dataset.fuo]=t.value});
document.addEventListener('change',e=>{const t=e.target;if(!M||M.kind!=='fu')return;if(t.dataset.fu&&t.tagName==='SELECT'){M[t.dataset.fu]=t.value;M.subject=M.body=undefined;renderModal()}else if(t.dataset.fuo&&t.tagName==='SELECT')M.out[t.dataset.fuo]=t.value});

FOCUS_ATTRS.push('data-ful');
document.addEventListener('input',e=>{const t=e.target;if(M&&M.kind==='fulist'&&t.dataset.ful){M[t.dataset.ful]=t.value;renderModal()}});
document.addEventListener('change',e=>{const t=e.target;if(M&&M.kind==='fulist'&&t.dataset.fulsort!=null){M.sort=t.value;renderModal()}});

/* =====================================================================
   Push Crew — the second hidden game (type "push" anywhere).
   Trucks back up to the haul road and dump. Drive the dozer into a pile
   to push it: down the lot it slides until it lands, sideways one square.
   Dirt lands on the lowest open square, so the lot fills bottom to top.
   Fill the lot before the shift ends; a truck that can't dump is a strike.
   Lots grow 5×5 → 10×10 → 15×15, and the trucks come faster.
   ===================================================================== */
const PC={W:600,H:680};
const pcSize=l=>Math.min(15,5*l),pcEvery=l=>[2.3,1.7,1.3,1.1,0.95,0.85][Math.min(5,l-1)],pcMaxTrucks=l=>l<=1?1:l===2?2:3;
function pcLevel(g,l){const N=pcSize(l);g.level=l;g.N=N;g.fill=Array.from({length:N},()=>new Array(N).fill(0));g.piles=[];g.trucks=[];g.left=N*N;g.spawn=1.2;g.every=pcEvery(l);
  g.limit=Math.round(N*N*g.every*1.4+25);g.time=g.limit;g.dz={r:-1,c:Math.floor(N/2),d:'down'};g.banner={t:2.2,txt:`Lot ${l}: ${N} × ${N}`};g.flash=0}
function pcNew(){const g={score:0,strikes:0,over:false,started:false,why:'',last:performance.now(),moveAt:0,best:0};pcLevel(g,1);return g}
const pcPileAt=(g,r,c)=>g.piles.find(p=>p.r===r&&p.c===c);
// a pile lands when it's over open ground with nothing open beneath it
function pcSettle(g){let again=true;while(again){again=false;for(const p of g.piles.slice()){if(p.r<0||g.fill[p.r][p.c])continue;if(p.r===g.N-1||g.fill[p.r+1][p.c]){g.fill[p.r][p.c]=1;g.piles.splice(g.piles.indexOf(p),1);g.left--;g.score++;g.pop={r:p.r,c:p.c,t:.35};again=true}}}
  if(g.left<=0&&!g.over){const bonus=Math.round(g.time/5);g.score+=bonus;g.strikes=Math.max(0,g.strikes-1);const l=g.level+1;g.best=Math.max(g.best,g.level);pcLevel(g,l);g.banner={t:2.6,txt:`Lot filled! +${bonus} for time · Lot ${l}: ${g.N} × ${g.N}`}}}
function pcMove(g,d){if(g.over)return;if(!g.started){g.started=true;return}const now=performance.now();if(now<g.moveAt)return;g.moveAt=now+70;
  const [dr,dc]={up:[-1,0],down:[1,0],left:[0,-1],right:[0,1]}[d];const z=g.dz;z.d=d;const r=z.r+dr,c=z.c+dc;if(r<-1||r>=g.N||c<0||c>=g.N)return;
  const p=pcPileAt(g,r,c);
  if(p){let nr=p.r+dr,nc=p.c+dc;if(nr<0||nr>=g.N||nc<0||nc>=g.N||pcPileAt(g,nr,nc)||(g.fill[nr][nc]&&nr!==0))return;   // jammed: the edge, another pile, or finished ground (dirt only rides on the top row)
    if(d==='down'){while(nr+1<g.N&&!g.fill[nr][nc]&&!g.fill[nr+1][nc]&&!pcPileAt(g,nr+1,nc))nr++}   // slides down the lot until it lands
    p.r=nr;p.c=nc;pcSettle(g)}
  z.r=r;z.c=c}
function pcStep(g,dt){if(g.banner){g.banner.t-=dt;if(g.banner.t<=0)g.banner=null}if(g.pop){g.pop.t-=dt;if(g.pop.t<=0)g.pop=null}if(g.flash>0)g.flash-=dt;if(g.over||!g.started)return;
  g.time-=dt;if(g.time<=0){g.time=0;pcOver(g,'The shift ended before the lot was filled.');return}
  g.spawn-=dt;if(g.spawn<=0&&g.trucks.length<pcMaxTrucks(g.level)){const open=[];for(let c=0;c<g.N;c++)if(!g.fill[0][c]&&!g.trucks.some(t=>t.c===c))open.push(c);
    const inFlight=g.piles.length+g.trucks.length;if(open.length&&inFlight<g.left){const w=1.8+g.N*0.07;g.trucks.push({c:open[Math.floor(Math.random()*open.length)],t:w,T:w});g.spawn=g.every*(0.8+Math.random()*0.4)}else g.spawn=.3}
  for(const t of g.trucks.slice()){t.t-=dt;if(t.t>0)continue;g.trucks.splice(g.trucks.indexOf(t),1);
    if(pcPileAt(g,0,t.c)||(g.dz.r===0&&g.dz.c===t.c)){g.strikes++;g.flash=.5;g.banner={t:1.6,txt:g.dz.r===0&&g.dz.c===t.c?'You were in the way! Strike.':'Truck couldn’t dump! Strike.'};if(g.strikes>=3){pcOver(g,'Three trucks couldn’t dump. The super sent you home.');return}}
    else{g.piles.push({r:0,c:t.c});pcSettle(g)}}}
function pcOver(g,why){g.over=true;g.why=why;g.best=Math.max(g.best,g.level-1);const cur=funStat(myId(),'push');
  funSave('push',g.score,{level:Math.max(num(cur?.data?.level)||0,g.best),plays:(num(cur?.data?.plays)||0)+1}).then(()=>{if(M&&M.kind==='push'){const b=$('.dirt-board');if(b)b.innerHTML='<b>Office high scores</b>'+funBoard('push',{fmt:(v,x)=>`${v} truck${v===1?'':'s'}${x.data.level?` · ${x.data.level} lot${x.data.level===1?'':'s'}`:''}`})}}).catch(()=>{})}
function pcDraw(g,x){const W=PC.W,H=PC.H,N=g.N;const pad=20;const cs=Math.floor(Math.min(58,(W-pad*2)/N,(H-70-34)/(N+2)));const top=70+cs;const gx=Math.round((W-cs*N)/2),ay=top,gy=top+cs;
  x.fillStyle='#22301F';x.fillRect(0,0,W,H);
  // HUD
  x.fillStyle='#F4F1E6';x.font='700 20px system-ui,sans-serif';x.textAlign='left';x.fillText(`Trucks ${g.score}`,pad,30);x.textAlign='center';x.fillText(`Lot ${g.level}  ·  ${g.left} to fill`,W/2,30);
  x.textAlign='right';x.fillStyle=g.time<15?'#FF8A6B':'#F4F1E6';x.fillText(`${Math.floor(g.time/60)}:${String(Math.floor(g.time%60)).padStart(2,'0')}`,W-pad,30);
  x.textAlign='left';x.font='600 13px system-ui,sans-serif';x.fillStyle='#C9C4B0';x.fillText('Strikes',pad,54);for(let i=0;i<3;i++){x.fillStyle=i<g.strikes?'#E0553A':'#4A5A45';x.beginPath();x.arc(pad+62+i*18,50,6,0,7);x.fill()}
  x.fillStyle='#4A5A45';x.fillRect(W-pad-160,45,160,8);x.fillStyle=g.time<15?'#E0553A':'#E8B23A';x.fillRect(W-pad-160,45,160*Math.max(0,g.time/g.limit),8);
  // haul road
  x.fillStyle='#8C8A80';x.fillRect(gx,ay,cs*N,cs);x.fillStyle='#A5A398';for(let c=0;c<N;c++)x.fillRect(gx+c*cs+cs*.42,ay+cs*.45,cs*.16,cs*.1);
  // lot
  for(let r=0;r<N;r++)for(let c=0;c<N;c++){const X=gx+c*cs,Y=gy+r*cs;x.fillStyle=g.fill[r][c]?'#C9A66B':'#3B2E22';x.fillRect(X,Y,cs,cs);
    if(g.fill[r][c]){x.strokeStyle='rgba(120,90,50,.35)';x.lineWidth=1;x.beginPath();x.moveTo(X+2,Y+cs*.33);x.lineTo(X+cs-2,Y+cs*.33);x.moveTo(X+2,Y+cs*.66);x.lineTo(X+cs-2,Y+cs*.66);x.stroke()}
    x.strokeStyle='rgba(0,0,0,.28)';x.lineWidth=1;x.strokeRect(X+.5,Y+.5,cs-1,cs-1)}
  if(g.pop){x.fillStyle=`rgba(255,240,180,${g.pop.t/.35*.7})`;x.fillRect(gx+g.pop.c*cs,gy+g.pop.r*cs,cs,cs)}
  // trucks backing up above the road, with a marker where the load will land
  for(const t of g.trucks){const X=gx+t.c*cs,k=1-t.t/t.T;const ty=ay-cs*.95+Math.min(1,k*1.4)*cs*.2;x.fillStyle='#E8B23A';x.fillRect(X+cs*.14,ty,cs*.72,cs*.62);x.fillStyle='#2B2B2B';x.fillRect(X+cs*.2,ty-cs*.2,cs*.6,cs*.22);
    x.fillStyle='#111';x.fillRect(X+cs*.1,ty+cs*.5,cs*.14,cs*.16);x.fillRect(X+cs*.76,ty+cs*.5,cs*.14,cs*.16);
    x.strokeStyle=Math.floor(t.t*6)%2?'#FF8A6B':'#FFD27A';x.lineWidth=2;x.setLineDash([4,3]);x.strokeRect(X+3,gy+3,cs-6,cs-6);x.setLineDash([]);x.fillStyle='#FFD27A';x.fillRect(X+3,gy+cs-7,(cs-6)*k,4)}
  // piles
  for(const p of g.piles){const X=gx+p.c*cs+cs/2,Y=gy+p.r*cs+cs/2;x.fillStyle='#7A5230';x.beginPath();x.ellipse(X,Y+cs*.08,cs*.38,cs*.3,0,0,7);x.fill();x.fillStyle='#96683E';x.beginPath();x.ellipse(X-cs*.06,Y-cs*.02,cs*.22,cs*.17,0,0,7);x.fill()}
  // dozer
  {const z=g.dz;const X=gx+z.c*cs+cs/2,Y=(z.r<0?ay:gy+z.r*cs)+cs/2;x.save();x.translate(X,Y);x.rotate({down:0,left:Math.PI/2,up:Math.PI,right:-Math.PI/2}[z.d]);
    x.fillStyle='#1C1C1C';x.fillRect(-cs*.36,-cs*.32,cs*.14,cs*.56);x.fillRect(cs*.22,-cs*.32,cs*.14,cs*.56);x.fillStyle='#F2B705';x.fillRect(-cs*.24,-cs*.28,cs*.48,cs*.46);x.fillStyle='#2F3A44';x.fillRect(-cs*.14,-cs*.2,cs*.28,cs*.2);
    x.fillStyle='#C9CED3';x.fillRect(-cs*.4,cs*.24,cs*.8,cs*.12);x.restore()}
  // messages
  x.textAlign='center';
  if(g.flash>0){x.fillStyle=`rgba(224,85,58,${g.flash*.5})`;x.fillRect(0,0,W,H)}
  if(g.banner&&!g.over){x.fillStyle='rgba(20,28,18,.82)';x.fillRect(W/2-250,H/2-28,500,48);x.fillStyle='#FFE9A8';x.font='700 17px system-ui,sans-serif';x.fillText(g.banner.txt,W/2,H/2+2)}
  if(!g.started){x.fillStyle='rgba(20,28,18,.86)';x.fillRect(40,H/2-90,W-80,170);x.fillStyle='#FFE9A8';x.font='800 24px system-ui,sans-serif';x.fillText('PUSH CREW',W/2,H/2-50);x.fillStyle='#F4F1E6';x.font='500 14px system-ui,sans-serif';
    ['Trucks dump at the top. Drive into a pile to push it.','Push it down the lot and it slides until it lands.','Clear each dump spot before the next truck. 3 strikes and you’re out.','Press any arrow key to start.'].forEach((s,i)=>x.fillText(s,W/2,H/2-18+i*24))}
  if(g.over){x.fillStyle='rgba(20,28,18,.88)';x.fillRect(40,H/2-80,W-80,160);x.fillStyle='#FF8A6B';x.font='800 24px system-ui,sans-serif';x.fillText('Shift over',W/2,H/2-40);x.fillStyle='#F4F1E6';x.font='500 15px system-ui,sans-serif';x.fillText(g.why,W/2,H/2-10);
    x.font='700 18px system-ui,sans-serif';x.fillText(`${g.score} truck${g.score===1?'':'s'} handled · ${g.best} lot${g.best===1?'':'s'} filled`,W/2,H/2+22);x.font='500 14px system-ui,sans-serif';x.fillStyle='#C9C4B0';x.fillText('Press Enter to go again',W/2,H/2+52)}
  x.fillStyle='#8FA088';x.font='500 12px system-ui,sans-serif';x.fillText('Haul road ▲   ·   dirt fills from the bottom ▼',W/2,H-14)}
function pushOpen(){M={kind:'push'};showModal();try{localStorage.setItem('bp-push-found','1')}catch(e){}setTimeout(pcInit,30)}
function pushModal(){const st=funStat(myId(),'push');return mhead('Push Crew','You found the other one. Keep up with the trucks.')+`<div class="mbody dirt-b"><canvas id="push-cv" width="${PC.W}" height="${PC.H}" tabindex="0"></canvas>
  <div class="dirt-ctl push-ctl"><button class="btn" data-push="left" aria-label="Left">◀</button><span><button class="btn" data-push="up" aria-label="Up">▲</button><button class="btn" data-push="down" aria-label="Down">▼</button></span><button class="btn" data-push="right" aria-label="Right">▶</button></div>
  <p class="small dim" style="text-align:center;margin:8px 0 0">Arrow keys or W A S D drive the dozer · push a pile down and it slides until it lands · a truck that can’t dump is a strike${st?` · your best: <b>${num(st.value)}</b> trucks`:''}</p>
  <div class="dirt-board"><b>Office high scores</b>${funBoard('push',{fmt:(v,x)=>`${v} truck${v===1?'':'s'}${x.data.level?` · ${x.data.level} lot${x.data.level===1?'':'s'}`:''}`})}</div></div>
  <div class="mfoot"><div></div><div class="r"><button class="btn" data-act="close">Back to work</button></div></div>`}
function pcInit(){const cv=$('#push-cv');if(!cv)return;const g=S.fun.push=pcNew();cv.focus();
  const loop=now=>{if(!M||M.kind!=='push'||S.fun.push!==g)return;const dt=Math.min(0.05,(now-g.last)/1000);g.last=now;pcStep(g,dt);pcDraw(g,cv.getContext('2d'));requestAnimationFrame(loop)};requestAnimationFrame(loop)}
let pushBuf='';
document.addEventListener('keydown',e=>{const t=e.target;const typing=t&&(t.tagName==='INPUT'||t.tagName==='TEXTAREA'||t.tagName==='SELECT'||t.isContentEditable);
  if(M&&M.kind==='push'&&S.fun.push){const g=S.fun.push;const d={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down'}[e.key];
    if(d){e.preventDefault();pcMove(g,d)}else if(e.key==='Enter'&&g.over){e.preventDefault();pcInit()}return}
  if(typing||M||e.ctrlKey||e.metaKey||e.altKey||!S.session||role()==='pending'||S.tracker||tabOff('fun')||e.key.length!==1)return;pushBuf=(pushBuf+e.key.toLowerCase()).slice(-4);if(pushBuf==='push'){pushBuf='';pushOpen()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-push]');if(b&&M&&M.kind==='push'&&S.fun.push){const g=S.fun.push;if(g.over)pcInit();else pcMove(g,b.dataset.push);$('#push-cv')?.focus();return}
  const t=e.target.closest('[data-act=fun-push]');if(t)pushOpen()});

/* =====================================================================
   Guide mode and Feedback mode — two helpers each person switches on or
   off for themselves.
   • Guide mode: Rivet, a little construction bot, walks to things on the
     page and explains them. One short tour per page.
   • Feedback mode: a card that follows you around and asks how each
     feature is working. The developer sees it as a user report.
   Both live outside the page (#assist) so redrawing the app never wipes them.
   ===================================================================== */
const AS={guide:false,fb:false,key:'',step:0,resting:false,list:false,rate:0,note:'',mine:null,asked:false};
const asKey=k=>`bp-${k}-${myId()||'x'}`;const asGet=k=>{try{return localStorage.getItem(asKey(k))}catch(e){return null}};const asSet=(k,v)=>{try{localStorage.setItem(asKey(k),v)}catch(e){}};
