  jobs:['Jobs list','Jobs'],'job:lines':['Job — budget lines','Jobs'],'job:log':['Job — cost log','Jobs'],'job:co':['Job — change orders','Jobs'],'modal:cx':['Change order window','Jobs'],'modal:jlog':['Log costs','Jobs'],
  'acct:overview':['Accounting — overview & WIP','Accounting'],'acct:billing':['Accounting — billing & pay apps','Accounting'],'acct:budgets':['Accounting — job budgets','Accounting'],'acct:costs':['Accounting — costs','Accounting'],'acct:lists':['Accounting — lists & codes','Accounting'],
