try{CALCS.forEach(c=>{FEATS['calc:'+c.id]=[c.name,'Calculators']})}catch(e){}
function asCtx(){if(!S.session||!S.profile||role()==='pending'||S.tracker)return '';if(M&&M.kind){const k='modal:'+M.kind;return ['welcome','aslist'].includes(M.kind)?'':k}
  const v=S.view;if(v==='dev')return '';if(v==='dashboard')return onlyMine()?'dashboard:mine':(!scopeView()&&S.dash==='board')||role()==='board'?'dashboard:board':'dashboard';
  if(v==='pipeline')return S.pv&&S.pv.mode&&S.pv.mode!=='cards'?'pipeline:'+S.pv.mode:'pipeline';if(v==='estimates')return S.estsTab==='tpl'?'estimates:tpl':'estimates';
  if(v==='estimate')return S.est&&S.est.data?(S.est.tpl?'estimate:tpl':'estimate:'+(S.est.tab||'build')):'estimates';if(v==='cb')return 'cb:'+((S.cb&&S.cb.book)||'material');
  if(v==='job')return 'job:'+((S.jt&&S.jt.tab)||'lines');if(v==='acct')return 'acct:'+((S.acct&&S.acct.tab)||'overview');
  if(v==='calc')return S.calcState&&S.calcState.id?'calc:'+S.calcState.id:'calc';if(v==='fun')return 'fun:'+((S.fun&&S.fun.tab)||'trophy');if(v==='help')return 'help:'+((S.help&&S.help.tab)||'tut');return v||''}
const asLabel=k=>(FEATS[k]||[])[0]||String(k).replace(/^modal:/,'').replace(/[:_-]+/g,' ').replace(/^./,c=>c.toUpperCase());
